/* ---------- Composer ---------- */
.cpx{display:flex;flex-direction:column;justify-content:flex-end;gap:14px;overflow-anchor:none;container-type:inline-size}
/* neither the composer nor the box it sits in anchors the page's scroll, so the page stays put as the thread grows and clears */
.stage-in:has(>.cpx){overflow-anchor:none}
/* no room is kept for the conversation (owner, 18 Nov): the thread and the box grow together (grow()) and stay centred in the
   stage. Its menus open over it from their buttons, down when there is room and up when there isn't, and the composer never
   moves for them (the visitor's clicks never move it). grow() must not clip the menus */
.cpx.growing{overflow:visible}
.cpx-thread{display:flex;flex-direction:column;gap:var(--dm-s-3)}
.cpx-thread:empty{display:none}
/* a message is a small card: its files and words 16px from its edges */
.cpx-thread .bub{padding:var(--dm-s-4)}
/* a message that is only attachments (owner, 19 Nov): the files sit on their own at the thread's right edge, as a chat app shows
   them, never in an empty bubble; with words they stay in the bubble, above the words */
.cpx-files{align-self:flex-end;max-width:85%;display:flex;flex-wrap:wrap;justify-content:flex-end;gap:6px}
.cpx-ag{font-size:14px;color:var(--dm-fg2);display:flex;gap:var(--dm-s-2);align-items:center}
/* the composer is a component, not a field: a quiet hairline and a soft shadow, the same while you type in it */
.cpx-box{position:relative;background:var(--dm-surface);border-radius:var(--dm-r-box);box-shadow:var(--dm-shadow);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.cpx-box{corner-shape:squircle;border-radius:var(--dm-r-box-sq)}}
/* everything in the box sits 16px from its edges (owner, 18 Nov): the attachments, the text, Send's edge and the dictation
   line; the attach button's glyph lines up with the text, and the toolbar's controls share one centre line */
.cpx-att{display:flex;gap:6px;flex-wrap:wrap;padding:16px 16px 0}
.cpx-att:empty{display:none}
.cpx-att .fchip{transition:color .32s,background .32s}
/* a chip never runs past the box on a narrow card: it shrinks to the row and its name trims */
.cpx-att .fchip{max-width:100%;min-width:0}
.cpx-att .fchip .n{min-width:0;overflow:hidden;text-overflow:ellipsis}
.cpx-att .fchip .x,.cpx-att .fchip .rt{display:grid;place-items:center;width:18px;height:18px;border-radius:50%;margin-right:-4px;color:var(--dm-muted)}
@media (hover:hover) and (pointer:fine){.cpx-att .fchip .x:hover,.cpx-att .fchip .rt:hover{background:var(--dm-row);color:var(--dm-fg)}}
.cpx-att .fchip .spin{width:10px;height:10px}
.cpx-att .fchip.ld{color:var(--dm-muted)}
.cpx-att .fchip.err{color:var(--dm-bad);background:var(--dm-bad-bg);box-shadow:none}
.cpx-att .fchip.err .rt{color:var(--dm-bad)}
.cpx-ta{display:block;width:100%;border:0;outline:0;resize:none;background:none;color:var(--dm-fg);font:inherit;font-size:14px;line-height:1.5;padding:14px 16px var(--dm-s-1);min-height:54px;max-height:160px;transition:color .32s}
.cpx-ta::placeholder{color:var(--dm-muted)}
.cpx-box[data-mode="voice"] .cpx-ta{color:var(--dm-fg2)}
.cpx-rows{display:grid;padding:4px 16px 16px}
.cpx-bar,.cpx-voice{grid-area:1/1;display:flex;align-items:center;gap:var(--dm-s-1);min-width:0;transition:opacity .32s var(--dm-ease),transform .42s var(--dm-ease)}
.cpx-voice{opacity:0;transform:translateY(6px);pointer-events:none;visibility:hidden;transition:opacity .32s var(--dm-ease),transform .42s var(--dm-ease),visibility 0s .32s}
.cpx-box[data-mode="voice"] .cpx-bar{opacity:0;transform:translateY(-6px);pointer-events:none}
.cpx-box[data-mode="voice"] .cpx-voice{opacity:1;transform:none;pointer-events:auto;visibility:visible;transition-delay:0s}
.cpx-bar>.ib{width:32px;height:32px;flex:none}
.cpx-add[aria-expanded="true"]{background:var(--dm-chip);color:var(--dm-fg)}
.cpx-bar .chip{height:32px;padding:0 10px;gap:6px;background:none;min-width:0;font-size:13px;color:var(--dm-fg2)}
.cpx-bar .chip[aria-expanded="true"]{background:var(--dm-row);color:var(--dm-fg)}
@media (hover:hover) and (pointer:fine){.cpx-bar .chip:hover{background:var(--dm-row);color:var(--dm-fg)}}
.cpx-bar .chip>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.cpx-bar .chip>svg:last-child{color:var(--dm-muted)}
/* a narrow box: the context and mode chips keep only their icon (the name stays for screen readers, and in the tooltip) */
/* (narrow, a chip shows only its icon and is a circle) */
@container (max-width:400px){.cpx-bar .chip{width:32px;padding:0;justify-content:center}.cpx-bar .chip>span{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}.cpx-bar .chip>svg:last-child{display:none}}
.cpx-send{width:32px;height:32px;border-radius:50%;display:grid;place-items:center;background:var(--dm-accent);color:var(--dm-on-accent);flex:none;transition:opacity .32s,transform .16s,background .16s}
@media (hover:hover) and (pointer:fine){.cpx-send:hover{background:var(--dm-accent-2)}}
.cpx-send[disabled]{opacity:1;cursor:not-allowed;background:var(--dm-dis-hatch),var(--dm-dis-fill);color:var(--dm-dis);box-shadow:var(--dm-soft-ring)}
/* dictation: a red dot and a clock while it listens, the words arriving in the box, then Cancel or Done */
.cpx-rec{display:inline-flex;align-items:center;gap:var(--dm-s-2);font-size:13px;color:var(--dm-fg)}
.cpx-dot{width:8px;height:8px;border-radius:50%;background:var(--dm-bad-mark);animation:cpxrec 1.6s var(--dm-ease-io) infinite}
@keyframes cpxrec{50%{opacity:.35}}
.cpx-tm{font-size:13px;margin-left:var(--dm-s-1)}
.cpx-voice .pill{flex:none}
.pp-plus,.pp-ctx,.pp-mode{width:264px}
.cpx-bar>.cpx-send{flex:none}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink Send alone presses */
.cpx :is(.ib,.pill,.chip):active,:root[data-style="clean"] .cpx .ib:active,:root [data-style="clean"] .cpx .ib:active,:root [data-style="clean"].cpx .ib:active{transform:none}
@media (max-width:480px){.cpx-bar .cpx-ctx>span{max-width:88px}}
/* Clean (owner, 18 Nov): the box takes the card's 22px round corners and its toolbar's controls are 28px. Send is the ink
   button. A file that failed keeps the chip's white with its words and mark in red, no red fill */
:root[data-style="clean"] .cpx-box,:root [data-style="clean"] .cpx-box,:root [data-style="clean"].cpx-box{border-radius:var(--dm-r-card)}
:root[data-style="clean"] .cpx-att,:root [data-style="clean"] .cpx-att,:root [data-style="clean"].cpx-att{gap:4px}
:root[data-style="clean"] .cpx-bar>.ib,:root [data-style="clean"] .cpx-bar>.ib,:root [data-style="clean"].cpx-bar>.ib{width:28px;height:28px}
:root[data-style="clean"] .cpx-bar .chip,:root [data-style="clean"] .cpx-bar .chip,:root [data-style="clean"].cpx-bar .chip{height:28px;padding:0 8px;transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@container (max-width:400px){:root[data-style="clean"] .cpx-bar .chip,:root [data-style="clean"] .cpx-bar .chip,:root [data-style="clean"].cpx-bar .chip{width:28px;padding:0}}
:root[data-style="clean"] :is(.cpx-add,.cpx-bar .chip)[aria-expanded="true"],:root [data-style="clean"] :is(.cpx-add,.cpx-bar .chip)[aria-expanded="true"],:root [data-style="clean"]:is(.cpx-add,.cpx-bar .chip)[aria-expanded="true"]{background:var(--dm-row-on)}
/* Send is the field's own Send (see the Clean section), 16px from the box's right and bottom edges, its corners the box's
   less those 16px */
:root[data-style="clean"] .cpx-send,:root [data-style="clean"] .cpx-send,:root [data-style="clean"].cpx-send{width:28px;height:28px;border-radius:calc(var(--dm-r-card) - 16px)}
:root[data-style="clean"] .cpx-att .fchip.err,:root [data-style="clean"] .cpx-att .fchip.err,:root [data-style="clean"].cpx-att .fchip.err{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent)}
:root[data-style="clean"] .cpx-att .fchip.err .ic,:root [data-style="clean"] .cpx-att .fchip.err .ic,:root [data-style="clean"].cpx-att .fchip.err .ic{color:var(--dm-bad-mark)}

