  const table = $('#df-table');
  const rows = [
    ['Button / Primary','Ready','space-16',null],
    ['Button / Ghost','Ready',['space-14','space-16'],null],
    ['Card / Pricing',['Draft','Ready'],['space-20','space-24'],null],
    ['Input / Text','Ready','space-12',null],
    ['Modal / Confirm',['Deprecated','Ready'],'space-24',null],
    ['Nav / Sidebar','Ready','space-8',null],
    ['Table / Row','Ready',['space-10','space-8'],null],
    ['Toast / Success','Ready','space-12',null]
  ];
  const owners = ['Web team','Web team','Product','Product','Product','Web team','Product','Web team'];
  let ts = [], cells = [];
  const cellHTML = v => Array.isArray(v) ? `<span class="cell-diff"><span class="old">${v[0]}</span><span class="new">${v[1]}</span></span>` : v;
  function build(){
    ts.forEach(clearTimeout); ts = [];
    table.innerHTML = `<div class="gt-row gt-head diff-cols"><div>Component</div><div>Status</div><div>Padding token</div><div>Owner</div></div><div class="gt-body">` +
      rows.map((r, i) => `<div class="gt-row diff-cols" data-i="${i}"><span class="scan-bar"></span><div style="font-weight:600">${r[0]}</div><div>${cellHTML(r[1])}</div><div style="font-family:var(--mono);font-size:12px">${cellHTML(r[2])}</div><div style="color:var(--muted)">${owners[i]}</div></div>`).join('') + '</div>';
    cells = $$('.cell-diff', table);
    $('#df-accept').disabled = true; $('#df-reject').disabled = true;
    $('#df-count').textContent = 'Scanning'; $('#df-status').textContent = 'Reviewing 8 components';
  }
  function sweep(){
    build();
    const rs = $$('.gt-body .gt-row', table);
    rs.forEach((r, i) => {
      ts.push(setTimeout(() => {
        rs.forEach(x => x.classList.remove('scanning')); r.classList.add('scanning');
        const d = $$('.cell-diff', r); if (d.length){ d.forEach(c => c.classList.add('show')); ambient('c11','pop'); } else ambient('c11','tick');
      }, 400 + i * 420));
    });
    ts.push(setTimeout(() => {
      rs.forEach(x => x.classList.remove('scanning'));
      swapText($('#df-count'), cells.length + ' edits'); swapText($('#df-status'), cells.length + ' edits proposed across 5 components');
      $('#df-accept').disabled = false; $('#df-reject').disabled = false; ambient('c11','done');
    }, 400 + rs.length * 420));
  }
  function resolve(ok){
    cells.forEach((c, i) => setTimeout(() => c.classList.add(ok ? 'accepted' : 'rejected'), i * 80));
    $('#df-accept').disabled = true; $('#df-reject').disabled = true;
    swapText($('#df-status'), ok ? 'All edits applied' : 'Edits rejected'); swapText($('#df-count'), ok ? 'Applied' : 'Rejected');
    Sound.play(ok ? 'done' : 'close');
  }
  $('#df-accept').addEventListener('click', () => resolve(true));
  $('#df-reject').addEventListener('click', () => resolve(false));
  $('#df-replay').addEventListener('click', () => { Sound.play('tab'); sweep(); });
  build(); whenSeen($('#c11'), sweep);
}

