  $('#sb-sec').addEventListener('click', e => { const b = e.currentTarget, open = b.getAttribute('aria-expanded') !== 'true'; b.setAttribute('aria-expanded', open); $('#sb-chats').classList.toggle('open', open); hl.style.opacity = '0'; Sound.play(open ? 'open' : 'close'); });
  $('#sb-tog').addEventListener('click', () => { const mini = sb.classList.toggle('mini'); hl.style.opacity = '0'; Sound.play(mini ? 'close' : 'open'); });
  $('.sb-up').addEventListener('click', () => Sound.play('select'));
}

