{
  const box = $('#ft-box'), f = { w:$('#ft-w'), h:$('#ft-h'), r:$('#ft-r'), o:$('#ft-o') }, type = $('#ft-type');
  function apply(){
    box.style.width = (+f.w.value || 0) + 'px'; box.style.height = (+f.h.value || 0) + 'px';
    box.style.borderRadius = (+f.r.value || 0) + 'px'; box.style.opacity = Math.max(0, Math.min(100, +f.o.value || 0)) / 100;
