  let busy = false;
  $('#ft-go').addEventListener('click', () => {
    if (busy) return; busy = true;
    const flip = +f.w.value === 260;
    const target = flip ? { w:200, h:130, r:0, o:70 } : { w:260, h:168, r:6, o:100 };
    const start = { w:+f.w.value, h:+f.h.value, r:+f.r.value, o:+f.o.value };
    const label = $('#ft-go-t'); swapText(label, 'Adjusting'); label.classList.add('shimmer'); Sound.play('open');
    Object.keys(f).forEach(k => { if (start[k] !== target[k]) f[k].parentElement.classList.add('chg'); });
    const t0 = performance.now(), dur = reduce ? 1 : 1100;
    const tick = now => {
      const t = Math.min(1, (now - t0) / dur), e = 1 - Math.pow(1 - t, 4);
      Object.keys(f).forEach(k => f[k].value = Math.round(start[k] + (target[k] - start[k]) * e));
      apply();
      if (t < 1) requestAnimationFrame(tick);
      else { busy = false; label.classList.remove('shimmer'); swapText(label, flip ? 'Tune with agent' : 'Revert'); Sound.play('done'); setTimeout(() => $$('.fld.chg').forEach(x => x.classList.remove('chg')), 1400); }
