/* ---------- voice capture ---------- */
{
  const vc = $('#vc'), wave = $('#vc-wave'), text = $('#vc-text'), mic = $('#vc-mic'), after = $('#vc-after'), stateEl = $('#vc-state'), timeEl = $('#vc-time');
  const N = 28; wave.innerHTML = '<i></i>'.repeat(N); const bars = $$('i', wave);
  const sentence = 'Make the pricing cards the same height and move the comparison table above the plans.';
  let live = false, raf = 0, ts = [], t0 = 0, phase = 0;
  function flat(){ bars.forEach(b => b.style.height = '4px'); }
  function animate(){
    if (!live) return;
    phase += .18;
    bars.forEach((b, n) => { const env = Math.sin(n / (N - 1) * Math.PI); const v = (Math.sin(phase + n * .7) * .5 + .5) * (.35 + Math.random() * .65); b.style.height = Math.max(3, Math.round(env * v * 26)) + 'px'; });
    const s = Math.floor((performance.now() - t0) / 1000); timeEl.textContent = '0:' + String(s).padStart(2, '0');
    raf = requestAnimationFrame(() => setTimeout(animate, 70));
  }
  function stop(auto){
    if (!live) return; live = false; vc.classList.remove('listening'); cancelAnimationFrame(raf); ts.forEach(clearTimeout); ts = []; flat();
    mic.setAttribute('aria-label', 'Start dictation'); stateEl.textContent = 'Transcribing'; stateEl.classList.add('shimmer'); Sound.play('off');
    setTimeout(() => {
      stateEl.classList.remove('shimmer'); stateEl.textContent = 'Transcript ready';
      text.innerHTML = sentence; text.classList.remove('enter'); void text.offsetWidth; text.classList.add('enter');
      after.classList.add('show'); Sound.play('pop');
    }, 900);
  }
  function start(){
    live = true; vc.classList.add('listening'); after.classList.remove('show'); t0 = performance.now();
    mic.setAttribute('aria-label', 'Stop dictation'); stateEl.textContent = 'Listening'; Sound.play('on');
    text.innerHTML = wordsHTML(sentence); const ws = $$('.w', text);
    ws.forEach((w, n) => ts.push(setTimeout(() => w.classList.add('in'), 500 + n * 260)));
    ts.push(setTimeout(() => stop(true), 500 + ws.length * 260 + 700));
    if (reduce){ bars.forEach((b, n) => b.style.height = Math.round(Math.sin(n / (N - 1) * Math.PI) * 14 + 3) + 'px'); } else animate();
  }
  mic.addEventListener('click', () => live ? stop() : start());
  $('#vc-retry').addEventListener('click', () => { Sound.play('tab'); start(); });
  $('#vc-send').addEventListener('click', () => { Sound.play('send'); showToast('Sent to agent'); after.classList.remove('show'); stateEl.textContent = 'Ready'; timeEl.textContent = '0:00'; text.innerHTML = '<span class="vc-ph">Tap the mic and describe the change you need</span>'; });
  flat();
}

c26.css:
/* ---------- Agent lanes ---------- */
/* each agent has its own hue (--dm-c, with its tint --dm-cb): its badge, its track, its tag and its stretch of the relay line that
   joins the badges. A hand-off sends a light down that line from one agent to the next, and the stretch it crossed stays lit */
/* the card's content, the head and the lanes, sits 16px in from every edge: each lane's badge starts and its tag ends on the
   head's 16px column, and a lane's hover fill reaches 8px out round it, into the padding (owner, 26 Nov) */
.aln{padding:var(--dm-s-4)}
/* the lanes' marks (tracks, lines, a finished badge) in livelier versions of the agents' hues, each 3:1 on the surface; their
   text keeps the agent's text colour. Dark mode's agent colours are light already, so they are used as they are */
.aln{--dm-aln-pb:#2a7bff;--dm-aln-pm:#1daa51;--dm-aln-pl:#7a5af5}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .aln{--dm-aln-pb:var(--dm-pb);--dm-aln-pm:#4ade80;--dm-aln-pl:var(--dm-pl)}}
:root[data-theme="dark"] .aln{--dm-aln-pb:var(--dm-pb);--dm-aln-pm:#4ade80;--dm-aln-pl:var(--dm-pl)}
/* on a card the lanes sit centred in the room kept for their tallest moment, and glide as a hand-off line opens and shuts */
.stage-in:has(>.aln){display:flex;flex-direction:column;justify-content:center}
.aln-h{display:flex;align-items:center;gap:10px;padding:0 0 var(--dm-s-2)}
.aln-ic{color:var(--dm-fg2);display:grid;transition:color .3s}
.aln.fin .aln-ic{color:var(--dm-ok)}
.aln-t{font-weight:500}
.aln-m{font-size:12.5px}
.aln-ct{font-size:12.5px;color:var(--dm-muted);margin-right:auto;white-space:nowrap}
.aln-ct::before{content:"·";margin-right:6px}
/* the head's words (the title, its time and its step count) share one baseline, whatever their sizes; the row round them stays
   centred, so the icon and Pause all sit on the title's line (owner, 23 Nov: the 12.5px time sat 2px above the 14px title) */
.aln-tx{display:flex;align-items:baseline;gap:10px;margin-right:auto}
.aln-rows{position:relative;margin-inline:calc(-1 * var(--dm-s-2))}
.aln-rows>*{position:relative}
.aln-lane{border-radius:calc(14px * var(--dm-rk-l,var(--dm-rk)));transition:background .3s}
/* the hover fills the lane's row, the button a person clicks; an open log below it stays clear */
.aln-row{border-radius:calc(14px * var(--dm-rk-l,var(--dm-rk)));transition:background .3s}
@media (hover:hover) and (pointer:fine){.aln-row:hover{background:var(--dm-row)}}
/* the lane at work carries a wash of its hue from the left */
/* the agent at work gets no tinted band behind its row: its pulsing badge and the Working spinner say it is active (owner,
   18 Nov) */
/* the relay line runs from badge to badge, through the lanes and the hand-offs between them, and stops short of each badge */
.aln-rows>*::before{content:"";position:absolute;left:24px;width:2px;top:0;bottom:0;background:var(--dm-line);pointer-events:none}
.aln-lane::before{top:50px}
.aln-lane:last-child::before{display:none}
.aln-lane::after{content:"";position:absolute;left:24px;width:2px;top:0;height:8px;background:var(--dm-line);pointer-events:none}
.aln-lane:first-child::after{display:none}
/* a stretch that has carried a hand-off is drawn by its one lit stroke (.aln-pk, below), so the grey under it steps aside
   and the line from badge to badge stays a single clean line */
.aln-rows>.aln-lane.sent::before,.aln-rows>.aln-lane.got::after,.aln-rows>.aln-hf.lit::before{background:transparent}
.aln-row{display:grid;grid-template-columns:34px minmax(0,1.2fr) minmax(0,1fr) auto;align-items:center;gap:var(--dm-s-3);width:100%;padding:var(--dm-s-3) var(--dm-s-2);text-align:left}
.aln-av{position:relative;width:34px;height:34px;border-radius:calc(11px * var(--dm-rk-l,var(--dm-rk)));display:grid;place-items:center;color:var(--dm-c);background:var(--dm-cb);transition:color .4s,background .4s}
.aln-av::before{content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none}
.aln-lane[data-s="working"] .aln-av{animation:alnbreathe 2.4s var(--dm-ease-io) infinite}
@keyframes alnbreathe{0%,100%{box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-c) 22%,transparent),0 0 0 1px color-mix(in srgb,var(--dm-fg) 0%,transparent)}50%{box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-c) 22%,transparent),0 0 0 5px color-mix(in srgb,var(--dm-fg) 6%,transparent)}}
/* the badge that takes a hand-off rings once as the light reaches it */
.aln-av.ping::before{animation:alnping .9s var(--dm-ease)}
@keyframes alnping{from{box-shadow:0 0 0 0 color-mix(in srgb,var(--dm-fg) 20%,transparent)}to{box-shadow:0 0 0 12px color-mix(in srgb,var(--dm-fg) 0%,transparent)}}
/* the badge at work is lifted onto the surface, with a hairline in its hue; its Working tag is a tint like every other status
   tag */
.aln-lane[data-s="working"] .aln-av{background:var(--dm-surface);box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-c) 22%,transparent)}
/* a finished agent's badge fills with its hue */
.aln-lane[data-s="done"] .aln-av{background:var(--dm-cb);color:var(--dm-c)}
.aln-who{min-width:0}
.aln-n{display:block;font-weight:500;font-size:13.5px}
.aln-a{display:block;font-size:12.5px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.aln-a.live{color:var(--dm-fg2)}
/* the track: one part a step. Finished parts are solid, the one in hand fills as the agent works, with a light running along it */
.aln-tr{display:flex;gap:3px}
.aln-tr i{flex:1;height:10px;border-radius:var(--dm-r-tiny,5px);background:color-mix(in srgb,var(--dm-cm) 16%,var(--dm-surface));position:relative;overflow:hidden}
.aln-tr i::after{content:"";position:absolute;inset:0;border-radius:inherit;background:var(--dm-cm);transform:scaleX(var(--dm-p,0));transform-origin:left;transition:transform .25s linear}
.aln-tr i.on::after{transform:scaleX(1);transition:transform .5s var(--dm-ease)}
.aln-tr i.run::after{background:linear-gradient(90deg,var(--dm-cm) 0 30%,color-mix(in srgb,var(--dm-cm) 30%,var(--dm-surface)) 50%,var(--dm-cm) 70% 100%) 0 0/250% 100%;animation:alnsheen 1.6s linear infinite}
/* given no step progress, the part in hand fills part way and keeps its light */
.aln-tr i.run.ind::after{transform:scaleX(.6);transition:transform 2.4s var(--dm-ease)}
@keyframes alnsheen{from{background-position:100% 0}to{background-position:-150% 0}}
.aln-st{min-width:92px;display:flex;justify-content:flex-end}
.aln-tg{background:var(--dm-cb);color:var(--dm-c)}
.aln-tg .spin{width:9px;height:9px}
/* (58px: the row's 12px, the 34px badge and the 12px gap, so the log starts under the agent's name) */
.aln-det{padding:0 var(--dm-s-2) var(--dm-s-3) 54px;font-size:12.5px;color:var(--dm-fg2)}
.aln-det div{display:flex;align-items:center;gap:var(--dm-s-2);padding:3px 0}
.aln-det div::before{content:"";width:5px;height:5px;border-radius:50%;background:var(--dm-c);flex:none}
.aln-det .muted{margin-left:auto}
/* a hand-off opens a line between the lanes, glides the lanes below down and closes again */
.aln-hf{transition-duration:var(--dm-t-slow)}
.aln-hand{padding:6px var(--dm-s-2) 6px 54px;font-size:12.5px;line-height:18px;color:var(--dm-fg2)}
.aln-hand b{font-weight:500}
.aln-hand .f{color:var(--dm-from)}.aln-hand .t{color:var(--dm-to)}
/* the hand-off draws the relay line from the sender's badge down to the taker's, in the gap between them (it never passes
   over a badge): a stroke that fills from the sender's hue into the taker's, then stays as the lit stretch (owner, 4 Nov).
   It is one element from badge to badge that follows them as the lanes move, so there is never a second line under it */
.aln-rows>.aln-pk::before{display:none}
.aln-pk{position:absolute;left:24px;top:0;width:2px;background:linear-gradient(var(--dm-from),var(--dm-to));transform-origin:50% 0;pointer-events:none;z-index:2}
@media (max-width:600px){
  .aln-row{grid-template-columns:34px minmax(0,1fr) auto;row-gap:var(--dm-s-2)}
  .aln-tr{grid-column:2 / -1;grid-row:2}
  .aln-lane::before{top:50px}
  .aln-ct{display:none}
  .aln-m{margin-right:auto}
}
