/* ---------- Toast stack ---------- */
/* each toast is the same size as the one in Toast: width, padding, type and icons */
/* the deck is as tall as the toasts in it (--dm-deckh, set as they arrive), growing with them, never keeping room for three
   (owner, 18 Nov: containers grow with their content in every style) */
.tsk-stack{position:relative;width:100%;max-width:380px;height:var(--dm-deckh,96px);isolation:isolate}
