/* 16px in all round (owner, 19 Nov); the icon, the title and the time share the title's line, and Close takes the time's
   place on it, its glyph on the content's right edge; hover fills are a quiet 5% so they show on the white toast */
.tsk-c{position:absolute;left:0;right:0;bottom:0;display:flex;align-items:flex-start;gap:var(--dm-s-3);padding:var(--dm-s-4);--dm-row:color-mix(in srgb,var(--dm-fg) 5%,transparent);background:var(--dm-surface);border-radius:var(--dm-r-card);box-shadow:var(--dm-shadow-toast);transition:transform .55s var(--dm-ease),opacity .45s var(--dm-ease),filter .45s;transform-origin:bottom center}
.tsk-c .g{width:28px;height:28px;margin-top:calc(8.775px - 14px);border-radius:50%;display:grid;place-items:center;flex:none}
/* (the title and its time share one baseline; the icon keeps its place on the title's line) */
.tsk-w{flex:1;min-width:0;display:flex;align-items:baseline;gap:var(--dm-s-3)}
.tsk-c .tx{flex:1;min-width:0;font-size:13px;line-height:1.35}
