  --dm-page:#f7f7f7; --dm-stage:#f7f7f7; --dm-surface:#ffffff; --dm-raised:#ffffff; --dm-strip:#fafafa;
  --dm-fg:#0a0a0a; --dm-fg2:#404040; --dm-muted:#6b6b6b; --dm-faint:#d4d4d4; --dm-rail:#e5e5e5;
  --dm-line:#e5e5e5; --dm-hair:rgba(0,0,0,.08); --dm-field-line:#e0e0e0; --dm-line-strong:#8f8f8f; --dm-field-line-strong:#b3b3b3;
  /* one hover and one selected fill for every row, option, segment, tab and ghost control (owner, 21 Nov: "hover and active
     states are inconsistent for clean style all over the components"): see-through, so they read the same on a card, a strip
     or a menu, and clearly visible in light and dark; selected is the same shape a step stronger */
  --dm-chip:#f3f3f3; --dm-hover:#ededed; --dm-press:#e6e6e6; --dm-wash:#fafafa; --dm-row:rgba(0,0,0,.05); --dm-row-on:rgba(0,0,0,.09);
  --dm-soft:#f3f3f3; --dm-soft-h:#ededed; --dm-soft-ring:inset 0 0 0 1px rgba(0,0,0,.06); --dm-dis:#a3a3a3;
  --dm-ghost:#ededed; --dm-ghost-2:#f4f4f4;
  --dm-ink:#0a0a0a; --dm-on-ink:#ffffff; --dm-on-btn:#ffffff;
  --dm-shadow:0 0 0 1px rgba(0,0,0,.07),0 1px 1px rgba(0,0,0,.04),0 2px 10px -4px rgba(0,0,0,.12);
  --dm-shadow-pop:0 0 0 1px rgba(0,0,0,.08),0 1px 1px rgba(0,0,0,.04),0 12px 28px -12px rgba(0,0,0,.22);
  --dm-shadow-toast:var(--dm-shadow-pop); --dm-shadow-lift:var(--dm-shadow-pop);
  --dm-tip-bg:#ffffff; --dm-tip-fg:#0a0a0a; --dm-tip-ring:0 0 0 1px rgba(0,0,0,.08),0 1px 1px rgba(0,0,0,.04),0 6px 16px -6px rgba(0,0,0,.18);
  --dm-btn-1:#2a2a2a; --dm-btn-2:#0a0a0a;
  --dm-btn-depth:inset 0 0 0 1px rgba(10,10,10,.92),inset 0 3px 6px -2px rgba(255,255,255,.42),inset 0 0 0 1px rgba(255,255,255,.06),inset 0 -3px 5px -3px rgba(0,0,0,.45),0 1px 2px rgba(0,0,0,.08),0 4px 12px -4px rgba(0,0,0,.16);
  --dm-btn-press:inset 0 0 0 1px rgba(10,10,10,.92),inset 0 1px 3px rgba(0,0,0,.5),inset 0 -3px 5px -3px rgba(0,0,0,.5),0 1px 1px rgba(0,0,0,.1);
  /* every button's edge is drawn inside it, so a primary and a secondary beside it are exactly the same height (owner, 18 Nov) */
  /* secondary buttons and dropdown triggers are flat (owner, 18 Nov): a hairline border and a light fill, no glow, shade or
     shadow; hover and press deepen the fill a little (the inset shadow is the fill) */
  --dm-btn2-1:#ffffff; --dm-btn2-2:#ffffff;
  --dm-btn2-depth:inset 0 0 0 1px rgba(0,0,0,.12);
  --dm-btn2-hover:inset 0 0 0 1px rgba(0,0,0,.16),inset 0 0 0 99px rgba(0,0,0,.025);
  --dm-btn2-press:inset 0 0 0 1px rgba(0,0,0,.18),inset 0 0 0 99px rgba(0,0,0,.05);
  --dm-knob:#ffffff; --dm-knob-shadow:0 0 0 1px rgba(0,0,0,.08),0 1px 2px rgba(0,0,0,.07); --dm-track-ring:inset 0 0 0 1px rgba(0,0,0,.03),inset 0 1px 3px rgba(0,0,0,.09);
  --dm-area:.07;
  /* round, never a squircle (owner, 18 Nov, replacing "everything fully round" of 17 Nov): pills and circles only for
     controls (buttons, chips, tags, toggles, switchers), avatars and dots, which have their own pill tokens (--dm-r-pill,
     --dm-r-tag). Everything else keeps ordinary rounded corners, a little rounder than Soft: fields, rows, panels, images, cells,
     events, flags and code boxes. Cards are 22px */
  --dm-rk:1; --dm-rk-s:1.6; --dm-rk-m:1.4; --dm-rk-l:1.3; --dm-r-tiny:4px;
  --dm-r-card:22px; --dm-r-lg:24px; --dm-r-in:10px; --dm-r-sm:8px; --dm-r-xs:6px; --dm-r-pill:999px;
  --dm-r-field:10px; --dm-r-field-sq:10px; --dm-r-box:16px; --dm-r-box-sq:16px; --dm-r-tag:999px; --dm-r-tag-sq:999px;
  --dm-ease:cubic-bezier(.23,1,.32,1); --dm-ease-io:cubic-bezier(.65,0,.35,1);
  /* calmer than it was (owner, 18 Nov: "it should be smoother"): hovers and fades 220ms, moves 340ms, entrances 560ms */
  --dm-t-fast:.22s; --dm-t:.34s; --dm-t-slow:.56s;
  --dm-on-tint-btn:var(--dm-btn2-depth); --dm-on-tint-btn-h:var(--dm-btn2-hover);
