/* ---------- search input ---------- */
{
  const root = $('#sx'), field = $('#sx-field'), q = $('#sx-q'), pop = $('#sx-pop'), list = $('#sx-list');
  const recent = ['pricing page', 'onboarding flow', 'brand tokens'];
  const items = [['Pricing page redesign','Project','folder'],['Pricing card component','Component','dashboard'],['Onboarding flow audit','Project','folder'],['Onboarding copy review','Doc','description'],['Brand tokens','Doc','description'],['Brand refresh for Northwind','Project','folder'],['Sidebar navigation','Component','dashboard'],['Handoff checklist','Doc','description']];
  let rows = [], idx = 0, timer = null;
  const hl = (t, v) => v ? esc(t).replace(new RegExp('(' + v.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + ')', 'ig'), '<mark>$1</mark>') : esc(t);
  function render(){
    const v = q.value.trim();
    root.classList.toggle('has', !!q.value);
    if (!v){
      rows = recent.map(r => [r, 'Recent', 'history']);
      list.innerHTML = '<div class="sx-h">Recent searches</div>' + rows.map((r, i) => `<button class="sx-it" data-i="${i}">${ic('history')}<span>${esc(r[0])}</span></button>`).join('');
    } else {
      rows = items.filter(it => it[0].toLowerCase().includes(v.toLowerCase()));
      list.innerHTML = rows.length ? '<div class="sx-h">Results</div>' + rows.map((r, i) => `<button class="sx-it" data-i="${i}">${ic(r[2])}<span>${hl(r[0], v)}</span><span class="ty">${r[1]}</span></button>`).join('') : `<div class="sx-empty">No matches for "${esc(v)}"</div>`;
    }
    idx = 0; paint();
  }
  function paint(){ $$('.sx-it', list).forEach((b, i) => b.classList.toggle('act', i === idx)); }
  function open(o){ pop.classList.toggle('show', o); q.setAttribute('aria-expanded', o); }
  function choose(i){ const r = rows[i]; if (!r) return; q.value = r[0]; root.classList.add('has'); open(false); Sound.play('select'); showToast('Searching for "' + r[0] + '"'); }
  q.addEventListener('focus', () => { field.classList.add('focus'); render(); open(true); });
  q.addEventListener('blur', () => { field.classList.remove('focus'); setTimeout(() => open(false), 150); });
  q.addEventListener('input', () => {
    root.classList.add('loading'); clearTimeout(timer); Sound.play('stream');
    timer = setTimeout(() => { root.classList.remove('loading'); render(); open(true); }, 260);
  });
  q.addEventListener('keydown', e => {
    const n = $$('.sx-it', list).length;
    if ((e.key === 'ArrowDown' || e.key === 'ArrowUp') && n){ e.preventDefault(); idx = (idx + (e.key === 'ArrowDown' ? 1 : -1) + n) % n; paint(); Sound.play('tick'); }
    else if (e.key === 'Enter'){ e.preventDefault(); choose(idx); }
    else if (e.key === 'Escape'){ open(false); q.blur(); }
  });
  list.addEventListener('mousedown', e => { const b = e.target.closest('.sx-it'); if (b){ e.preventDefault(); choose(+b.dataset.i); } });
  $('#sx-clear').addEventListener('mousedown', e => { e.preventDefault(); q.value = ''; render(); q.focus(); Sound.play('tick'); });
