    if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k'){
      const r = $('#c53').getBoundingClientRect(); if (r.bottom < 0 || r.top > innerHeight) return;
      e.preventDefault(); q.focus(); Sound.play('open');
    }
  });
}

