/* ---------- sign in ---------- */
{
  const sn = $('#sn');
  const google = $('#so .so-btn[data-p="Google"] .so-logo').innerHTML;
  function build(){
    sn.innerHTML = `<div class="enter">
      <span class="sn-mark">${ic('stars')}</span>
      <h3 class="sn-h">Welcome back</h3><p class="sn-sub">Sign in to pick up where your team left off.</p>
      <button class="so-btn" style="width:100%" id="sn-g"><span class="so-logo">${google}</span><span class="so-t">Sign in with Google</span></button>
      <div class="sn-or">or</div>
      <div class="fz" id="sn-e"><label class="fz-l" for="sn-em">Email</label><div class="fz-in"><input id="sn-em" type="email" placeholder="you@company.com" autocomplete="off"></div><span class="fz-e">Enter the email you signed up with</span></div>
      <div class="fz" id="sn-p"><label class="fz-l" for="sn-pw">Password <button type="button" id="sn-forgot">Forgot password?</button></label><div class="fz-in"><input id="sn-pw" type="password" placeholder="Your password"><button type="button" class="fz-eye" id="sn-eye" aria-label="Show password"></button></div><span class="fz-e">Enter your password</span></div>
      <div class="fz-row"><label class="fz-check"><span class="cb" id="sn-rem">${ic('check')}</span>Keep me signed in</label></div>
      <button class="bt bt-primary" id="sn-go">Sign in</button>
      <p class="sn-foot">New here? <button type="button" id="sn-new">Create an account</button></p>
    </div>`;
    const eye = $('#sn-eye'), pw = $('#sn-pw'); eye.innerHTML = eyeSVG(false);
    eye.addEventListener('click', () => { const show = pw.type === 'password'; pw.type = show ? 'text' : 'password'; eye.innerHTML = eyeSVG(show); eye.setAttribute('aria-label', show ? 'Hide password' : 'Show password'); Sound.play('tick'); });
    $('#sn-rem').parentElement.addEventListener('click', () => { $('#sn-rem').classList.toggle('on'); Sound.play('tick'); });
    ['sn-em','sn-pw'].forEach(id => $('#' + id).addEventListener('input', e => e.target.closest('.fz').classList.remove('err')));
    $('#sn-g').addEventListener('click', () => { Sound.play('tab'); showToast('Redirecting to Google'); });
    $('#sn-forgot').addEventListener('click', () => { Sound.play('tick'); showToast('Reset link sent'); });
    $('#sn-new').addEventListener('click', () => { Sound.play('tick'); showToast('Opening sign up'); });
    $('#sn-go').addEventListener('click', submit);
    sn.addEventListener('keydown', e => { if (e.key === 'Enter' && e.target.matches('input')) submit(); });
  }
  function eyeSVG(open){ return open ? '<svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 3l18 18M10.6 10.6a2 2 0 0 0 2.8 2.8M9.4 5.2A9.7 9.7 0 0 1 12 5c5 0 9 5 9 7a8.6 8.6 0 0 1-2.2 3.2M6.2 6.6C4 8 3 10.4 3 12c0 2 4 7 9 7a9 9 0 0 0 4.3-1.1"/></svg>' : '<svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 12c0-2 4-7 9-7s9 5 9 7-4 7-9 7-9-5-9-7z"/><circle cx="12" cy="12" r="2.6"/></svg>'; }
  function submit(){
    const em = $('#sn-em'), pw = $('#sn-pw');
    const okE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(em.value.trim()), okP = pw.value.length > 0;
    $('#sn-e').classList.toggle('err', !okE); $('#sn-p').classList.toggle('err', !okP);
    if (!okE || !okP){ Sound.play('fail'); (okE ? pw : em).focus(); return; }
    const go = $('#sn-go'); go.disabled = true; go.innerHTML = '<i class="bt-spin"></i>Signing in'; Sound.play('tab');
    setTimeout(() => {
      Sound.play('done');
      morph(sn, () => { sn.innerHTML = `<div class="sn-done enter"><span class="nbox" style="color:var(--success)">${ic('check_circle','icon-in')}</span><h3 class="sn-h">You're in</h3><p class="sn-sub" style="margin:0">Signed in as ${esc(em.value.trim())}</p><button class="bt bt-secondary bt-sm" id="sn-out" style="margin-top:6px">Sign out</button></div>`; $('#sn-out').addEventListener('click', () => { Sound.play('tab'); morph(sn, build); }); });
    }, 1200);
  }
  build();
}

