/* ---------- custom select ---------- */
function enhanceSelect(sel){
  if (!sel || sel._cs) return; sel._cs = true; sel.classList.add('ns-hide');
  const btn = document.createElement('button'); btn.type = 'button'; btn.className = 'csel';
  btn.setAttribute('aria-haspopup', 'listbox'); btn.setAttribute('aria-expanded', 'false');
  const lab = () => { const o = sel.options[sel.selectedIndex]; btn.textContent = o ? o.textContent : ''; };
  sel.after(btn); lab();
  const pop = document.createElement('div'); pop.className = 'csel-pop'; pop.setAttribute('role', 'listbox'); document.body.appendChild(pop);
  let idx = 0;
  const paint = () => $$('.csel-i', pop).forEach((b, i) => b.classList.toggle('act', i === idx));
  function open(){
    pop.innerHTML = [...sel.options].map((o, i) => `<button type="button" class="csel-i ${i === sel.selectedIndex ? 'sel' : ''}" role="option" data-i="${i}">${o.textContent}${ic('check','sm')}</button>`).join('');
    idx = sel.selectedIndex; paint();
    const host = btn.closest('.fz-in,.fld') || btn, r = host.getBoundingClientRect();
    pop.style.minWidth = r.width + 'px'; pop.style.left = r.left + 'px'; pop.style.top = (r.bottom + 6) + 'px';
    pop.classList.add('show'); btn.setAttribute('aria-expanded', 'true'); Sound.play('open');
  }
  function close(){ if (!pop.classList.contains('show')) return; pop.classList.remove('show'); btn.setAttribute('aria-expanded', 'false'); }
  function choose(i){ sel.selectedIndex = i; lab(); sel.dispatchEvent(new Event('change', { bubbles:true })); close(); Sound.play('select'); btn.focus(); }
  btn.addEventListener('click', e => { e.preventDefault(); pop.classList.contains('show') ? close() : open(); });
  btn.addEventListener('keydown', e => {
    const n = sel.options.length, isOpen = pop.classList.contains('show');
    if (!isOpen && ['ArrowDown','Enter',' '].includes(e.key)){ e.preventDefault(); open(); return; }
    if (!isOpen) return;
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp'){ e.preventDefault(); idx = (idx + (e.key === 'ArrowDown' ? 1 : -1) + n) % n; paint(); Sound.play('tick'); }
    else if (e.key === 'Enter'){ e.preventDefault(); choose(idx); }
    else if (e.key === 'Escape' || e.key === 'Tab') close();
  });
  pop.addEventListener('mousedown', e => { const b = e.target.closest('.csel-i'); if (b){ e.preventDefault(); choose(+b.dataset.i); } });
  document.addEventListener('pointerdown', e => { if (!pop.contains(e.target) && !btn.contains(e.target)) close(); });
  addEventListener('scroll', close, { passive:true });
  sel.addEventListener('change', lab);
}
enhanceSelect($('#as-model')); enhanceSelect($('#ft-type'));

/* ---------- form ---------- */
{
  const fm = $('#fm');
  const services = ['Brand','Website','Product','Development','Motion'];
  function build(){
    fm.innerHTML = `<div class="enter">
      <h3 class="fm-h">Start a project</h3><p class="fm-sub">Tell us a little about what you need and we will reply within one working day.</p>
      <div class="fm-grid">
        <div class="fz" id="fm-n"><label class="fz-l" for="fm-name">Full name</label><div class="fz-in"><input id="fm-name" placeholder="Maya Chen" autocomplete="off"></div><span class="fz-e">Add your name so we know who to reply to</span></div>
        <div class="fz" id="fm-e"><label class="fz-l" for="fm-email">Work email</label><div class="fz-in"><input id="fm-email" placeholder="maya@company.com" autocomplete="off"></div><span class="fz-e">That email doesn't look right</span></div>
        <div class="fz"><label class="fz-l" for="fm-co">Company</label><div class="fz-in"><input id="fm-co" placeholder="Northwind Labs" autocomplete="off"></div></div>
        <div class="fz"><label class="fz-l" for="fm-stage">Stage</label><div class="fz-in"><select id="fm-stage"><option>Pre-seed</option><option selected>Seed</option><option>Series A</option><option>Series B or later</option></select>${ic('expand_more')}</div></div>
        <div class="fz full"><span class="fz-l">What do you need</span><div class="fm-chips" id="fm-chips">${services.map((s, i) => `<button type="button" class="fm-chip ${i === 1 ? 'on' : ''}">${ic('check')}${s}</button>`).join('')}</div></div>
        <div class="fz full" style="margin-top:14px"><label class="fz-l" for="fm-msg">Project details <span class="fm-count" id="fm-count">0 / 400</span></label><div class="fz-in area"><textarea id="fm-msg" maxlength="400" placeholder="Goals, timeline, links to anything we should see"></textarea></div></div>
      </div>
      <div class="fm-foot"><label class="fz-check"><span class="cb on" id="fm-news">${ic('check')}</span>Send me the monthly design notes</label><button class="bt bt-primary fm-submit" id="fm-go">Send enquiry</button></div>
    </div>`;
    enhanceSelect($('#fm-stage'));
    $$('.fm-chip', fm).forEach(c => c.addEventListener('click', () => { c.classList.toggle('on'); Sound.play('tick'); }));
    $('#fm-news').parentElement.addEventListener('click', () => { $('#fm-news').classList.toggle('on'); Sound.play('tick'); });
    const msg = $('#fm-msg'); msg.addEventListener('input', () => { $('#fm-count').textContent = msg.value.length + ' / 400'; });
    ['fm-name','fm-email'].forEach(id => $('#' + id).addEventListener('input', e => e.target.closest('.fz').classList.remove('err')));
    $('#fm-go').addEventListener('click', submit);
  }
  function submit(){
    const n = $('#fm-name'), e = $('#fm-email');
    const okN = n.value.trim().length > 1, okE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e.value.trim());
    $('#fm-n').classList.toggle('err', !okN); $('#fm-e').classList.toggle('err', !okE);
    if (!okN || !okE){ Sound.play('fail'); (okN ? e : n).focus(); return; }
    const go = $('#fm-go'); go.disabled = true; go.innerHTML = '<i class="bt-spin"></i>Sending'; Sound.play('tab');
    const picked = $$('.fm-chip.on', fm).map(c => c.textContent.trim());
    setTimeout(() => {
      Sound.play('done');
      morph(fm, () => { fm.innerHTML = `<div class="sn-done enter" style="padding:26px 0 18px"><span class="nbox" style="color:var(--success)">${ic('check_circle','icon-in')}</span><h3 class="sn-h">Thanks, ${esc(n.value.trim().split(' ')[0])}</h3><p class="sn-sub" style="margin:0;max-width:40ch">We got your enquiry${picked.length ? ' about ' + esc(picked.join(', ').toLowerCase()) : ''} and will reply to ${esc(e.value.trim())} soon.</p><button class="bt bt-secondary bt-sm" id="fm-again" style="margin-top:6px">Send another</button></div>`; $('#fm-again').addEventListener('click', () => { Sound.play('tab'); morph(fm, build); }); });
    }, 1200);
  }
  build();
}

