/* ---------- notifications ---------- */
{
  const list = $('#nt-list'), badge = $('#nt-badge'), mark = $('#nt-mark');
  let tab = 'all';
  const items = [
    { id:1, kind:'request', who:'Maya Chen', text:'<b>Maya Chen</b> asked for edit access to <b>Pricing page v2</b>', t:'4 min ago', unread:true, mention:false },
    { id:2, kind:'file', who:'Oscar Lind', text:'<b>Oscar Lind</b> uploaded a file to <b>Brand refresh</b>', t:'1 hour ago', unread:true, mention:false, file:['Northwind_logo_set.fig', '3.4 MB'] },
    { id:3, kind:'mention', who:'Priya Nair', text:'<b>Priya Nair</b> mentioned you in <b>Onboarding copy review</b>', t:'2 hours ago', unread:true, mention:true },
    { id:4, kind:'done', ini:'JW', tone:'pm', text:'<b>Jonas Weber</b> finished <b>Sidebar navigation</b>', t:'Yesterday', unread:false, mention:false },
    { id:5, kind:'done', ini:'ID', tone:'pp', text:'<b>Ines Duarte</b> commented on <b>Launch checklist</b>', t:'Yesterday', unread:false, mention:true }
  ];
  const tones = { pm:['var(--pm-bg)','var(--pm-tx)'], pp:['var(--pp-bg)','var(--pp-tx)'] };
  function count(){ const n = items.filter(i => i.unread && !i.archived).length; badge.textContent = n; badge.classList.toggle('zero', !n); mark.disabled = !n; }
  function row(it){
    const av = it.who ? avatar(it.who) : `<span class="nt-ini" style="background:${tones[it.tone][0]};color:${tones[it.tone][1]}">${it.ini}</span>`;
    let extra = '';
    if (it.kind === 'request') extra = it.decided ? `<div class="nt-acts"><span class="pill ${it.decided === 'Approved' ? 'done' : 'todo'}"><i></i><span>${it.decided}</span></span></div>` : `<div class="nt-acts"><button class="bt bt-primary bt-sm" data-a="approve">Approve</button><button class="bt bt-secondary bt-sm" data-a="decline">Decline</button></div>`;
    if (it.file) extra = `<div class="nt-file"><span class="fi">${ic('description','sm')}</span><div><div class="fn">${it.file[0]}</div><div class="fs">${it.file[1]}</div></div></div>`;
    return `<div class="nt-it ${it.unread ? 'unread' : ''}" data-id="${it.id}"><span class="nt-dot"></span>${av}<div class="nt-txt">${it.text}<span class="nt-time">${it.t}</span>${extra}</div>${tab === 'archive' ? '' : `<button class="nt-x" aria-label="Archive">${ic('close','sm')}</button>`}</div>`;
  }
  function render(first){
    const change = () => {
      const shown = items.filter(i => tab === 'archive' ? i.archived : !i.archived && (tab === 'all' || i.mention));
      list.innerHTML = shown.length ? shown.map(row).join('') : `<div class="nt-empty enter">${ic(tab === 'archive' ? 'folder' : 'notifications')}${tab === 'archive' ? 'Nothing archived yet' : 'You are all caught up'}</div>`;
    };
    first ? change() : morph(list.parentElement, change);
    count();
  }
  list.addEventListener('click', e => {
    const el = e.target.closest('.nt-it'); if (!el) return; const it = items.find(i => i.id === +el.dataset.id);
    const a = e.target.closest('[data-a]');
    if (a){ it.decided = a.dataset.a === 'approve' ? 'Approved' : 'Declined'; it.unread = false; Sound.play(it.decided === 'Approved' ? 'done' : 'close'); render(); return; }
    if (e.target.closest('.nt-x')){ it.archived = true; it.unread = false; Sound.play('close'); el.style.transition = 'opacity .2s, transform .3s var(--ease)'; el.style.opacity = '0'; el.style.transform = 'translateX(16px)'; setTimeout(() => render(), 200); return; }
    if (it.unread){ it.unread = false; el.classList.remove('unread'); count(); Sound.play('tick'); }
  });
  mark.addEventListener('click', () => { items.forEach(i => i.unread = false); $$('.nt-it', list).forEach(el => el.classList.remove('unread')); count(); Sound.play('done'); });
  initInTabs($('#nt-tabs'), v => { tab = v; render(); });
  render(true);
}

