      ${fld('pay-num','Card number','<input id="pay-num" inputmode="numeric" placeholder="1234 1234 1234 1234" autocomplete="off"><span class="pay-brands" id="pay-brands"><span data-b="visa">VISA</span><span data-b="mc">MC</span><span data-b="amex">AMEX</span></span>','Card number looks incomplete')}
      <div class="pay-row">${fld('pay-exp','Expiry','<input id="pay-exp" inputmode="numeric" placeholder="MM / YY" autocomplete="off">','Use a future date')}${fld('pay-cvc','Security code','<input id="pay-cvc" inputmode="numeric" placeholder="123" maxlength="4" autocomplete="off">','3 or 4 digits')}</div>
      ${fld('pay-name','Name on card','<input id="pay-name" placeholder="Maya Chen" autocomplete="off">','Add the name on the card')}
      <div class="pay-row">${fld('pay-country','Country',`<select id="pay-country">${['Poland','United Kingdom','United States','Germany','France','Netherlands'].map(c => `<option>${c}</option>`).join('')}</select>${ic('expand_more')}`,'')}${fld('pay-zip','Postcode','<input id="pay-zip" placeholder="80-001" autocomplete="off">','')}</div>`;
    if (method === 'bank') return `
      ${fld('pay-email','Email','<input id="pay-email" type="email" placeholder="you@company.com" autocomplete="off">','Enter a valid email')}
      ${fld('pay-iban','IBAN','<input id="pay-iban" placeholder="PL61 1090 1014 0000 0712 1981 2874" autocomplete="off">','Enter your IBAN')}
      <p class="pay-wnote" style="text-align:left;margin:0">We will email a mandate to confirm the debit before your first payment.</p>`;
    const logo = method === 'apple' ? apple : google;
    return `<div class="pay-wallet"><button class="pay-wbtn" id="pay-wallet-go"><span style="display:flex">${logo.replace('fill="currentColor"', 'fill="#fff"')}</span>Pay with ${method === 'apple' ? 'Apple Pay' : 'Google Pay'}</button><div class="pay-wnote">You will confirm the payment in a secure ${method === 'apple' ? 'Apple Pay' : 'Google Pay'} sheet.</div></div>`;
  }
  function build(first){
    const put = () => {
      main.innerHTML = `<div class="enter"><div class="pay-methods" role="tablist">${methods.map(m => `<button class="pay-m ${m[0] === method ? 'on' : ''}" data-m="${m[0]}" role="tab" aria-selected="${m[0] === method}"><span class="lg">${m[2]}</span>${m[1]}</button>`).join('')}</div><div id="pay-body">${body()}</div></div>`;
      wire();
    };
    first ? put() : morph(main, put);
  }
  function wire(){
    $$('.pay-m', main).forEach(b => b.addEventListener('click', () => { if (b.dataset.m === method) return; method = b.dataset.m; Sound.play('tab'); build(); }));
    const num = $('#pay-num'), exp = $('#pay-exp'), cvc = $('#pay-cvc');
    if (num) num.addEventListener('input', () => {
      const d = num.value.replace(/\D/g, '').slice(0, 16); num.value = d.replace(/(.{4})/g, '$1 ').trim();
      const b = /^4/.test(d) ? 'visa' : /^5[1-5]/.test(d) ? 'mc' : /^3[47]/.test(d) ? 'amex' : '';
      $$('#pay-brands span').forEach(s => s.classList.toggle('on', s.dataset.b === b));
    });
    if (exp) exp.addEventListener('input', e => {
      let d = exp.value.replace(/\D/g, '').slice(0, 4);
      if (d.length === 1 && +d > 1) d = '0' + d;
      exp.value = d.length > 2 ? d.slice(0, 2) + ' / ' + d.slice(2) : d;
    });
    if (cvc) cvc.addEventListener('input', () => { cvc.value = cvc.value.replace(/\D/g, ''); });
    $$('input', main).forEach(i => i.addEventListener('input', () => { const f = i.closest('.fz'); if (f) f.classList.remove('err'); }));
    const w = $('#pay-wallet-go'); if (w) w.addEventListener('click', () => pay(true));
    const c = $('#pay-country'); if (c) enhanceSelect(c);
  }
  function valid(){
    const bad = [];
    const v = id => ($('#' + id) || {}).value || '';
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v('pay-email').trim())) bad.push('pay-email');
    if (method === 'card'){
      if (v('pay-num').replace(/\D/g, '').length < 15) bad.push('pay-num');
      const m = v('pay-exp').match(/^(\d{2}) \/ (\d{2})$/), now = new Date();
      if (!m || +m[1] < 1 || +m[1] > 12 || new Date(2000 + +m[2], +m[1], 0) < now) bad.push('pay-exp');
      if (!/^\d{3,4}$/.test(v('pay-cvc'))) bad.push('pay-cvc');
      if (!v('pay-name').trim()) bad.push('pay-name');
    }
    if (method === 'bank' && v('pay-iban').replace(/\s/g, '').length < 15) bad.push('pay-iban');
    $$('.fz', main).forEach(f => f.classList.toggle('err', bad.includes(f.id.replace(/-f$/, ''))));
    return !bad.length;
  }
  function pay(wallet){
    if (!wallet && !valid()){ Sound.play('fail'); return; }
    const go = $('#pay-go'); go.disabled = true; $('#pay-go-t').textContent = 'Processing'; Sound.play('tab');
    setTimeout(() => {
      Sound.play('done');
      morph(main, () => { main.innerHTML = `<div class="pay-done enter"><span class="nbox">${ic('check_circle','icon-in')}</span><div class="t">Payment complete</div><div class="d">${total()} paid with ${methods.find(m => m[0] === method)[1]}. Your receipt is on its way.</div><button class="bt bt-secondary bt-sm" id="pay-again" style="margin-top:12px">Start over</button></div>`; $('#pay-again').addEventListener('click', () => { Sound.play('tab'); go.disabled = false; swapText($('#pay-go-t'), 'Pay ' + total()); build(); }); });
      $('#pay-go-t').textContent = 'Paid';
    }, 1300);
  }
  $('#pay-go').addEventListener('click', () => pay(method === 'apple' || method === 'google'));
  $('#pay-apply').addEventListener('click', () => {
    const f = $('#pay-code-f'), code = $('#pay-code').value.trim().toUpperCase();
    if (code !== 'LAUNCH10'){ f.classList.add('err'); Sound.play('fail'); return; }
    f.classList.remove('err'); discount = true; $('#pay-disc').classList.add('open');
    swapText($('#pay-total'), total()); swapText($('#pay-go-t'), 'Pay ' + total()); Sound.play('done');
  });
  $('#pay-code').addEventListener('input', () => $('#pay-code-f').classList.remove('err'));
  build(true);
}

