/* ---------- ticket list ---------- */
{
  const list = $('#tkl-list');
  const T = {
    open:[['Joanna Kim','alternate_email','Charged twice for October','I can see two payments on my card for the same invoice.','2m','late','12m left',1],['Sam Rivera','chat_bubble','Can\u2019t invite my team','The invite link says it has expired every time.','9m','warn','38m left',1],['Ines Duarte','chat_bubble','Export to CSV is empty','The file downloads but has only the header row.','24m','ok','3h left',0],['Jonas Weber','alternate_email','Change billing email','We moved finance to a new address last week.','1h','ok','5h left',0],['Tom Becker','alternate_email','SSO setup question','Which SAML attributes do you need from Okta?','2h','ok','1d left',0]],
    pending:[['Priya Nair','alternate_email','Refund for annual plan','Waiting on the customer to confirm the account.','1d','ok','Waiting',0],['Oscar Lind','chat_bubble','API rate limits','Asked for their expected request volume.','2d','ok','Waiting',0],['Maya Chen','alternate_email','Custom domain not verifying','Sent DNS steps, waiting for them to update.','3d','ok','Waiting',0]],
    solved:[['Sam Rivera','chat_bubble','Reset two-factor','Solved by the agent in 46 seconds.','Mon','ok','Solved',0],['Joanna Kim','alternate_email','Invoice in euros','Switched the currency and resent the invoice.','Mon','ok','Solved',0]]
  };
  const row = (t, i, on) => `<button class="tkl-r ${on ? 'on' : ''}" data-i="${i}">${t[7] ? '<i class="tkl-dot"></i>' : ''}${avatar(t[0])}<span class="tkl-m"><span class="tkl-n">${t[0]}${ic(t[1],'sm')}</span><span class="tkl-s">${t[2]}</span><span class="tkl-p">${t[3]}</span></span><span class="tkl-side"><span class="tkl-time">${t[4]}</span><span class="tkl-sla ${t[5]}">${t[6]}</span></span></button>`;
  const show = (k, anim) => { list.innerHTML = T[k].map((t, i) => row(t, i, i === 0 && k === 'open')).join(''); hydrate(list);
    if (anim && !reduce) $$('.tkl-r', list).forEach((r, i) => r.animate([{ opacity:0, transform:'translateY(8px)' }, { opacity:1, transform:'none' }], { duration:360, delay:i * 45, easing:'cubic-bezier(.16,1,.3,1)', fill:'backwards' })); };
  show('open', false);
  list.addEventListener('click', e => { const r = e.target.closest('.tkl-r'); if (!r) return; $$('.tkl-r', list).forEach(x => x.classList.toggle('on', x === r)); const d = r.querySelector('.tkl-dot'); if (d) d.remove(); Sound.play('tab'); });
  segInit($('#tkl-seg'), v => { show(v, true); Sound.play('tab'); });
}

