/* ---------- Model picker ---------- */
/* a trigger that names the model and how hard it thinks, over the open list: speed, quality and cost as five-step meters
   with the real numbers on hover, and the thinking effort under them as a small dropdown */
.mpk{position:relative;display:flex;flex-direction:column;gap:var(--dm-s-2);width:100%;max-width:420px;margin:0 auto}
.mpk-top{display:flex;align-items:center;justify-content:space-between;gap:10px}
.mpk-lb{font-size:12.5px}
/* Soft's model trigger is a flat button with a faint hairline (owner, 18 Nov: minimal), a step stronger under the pointer */
.mpk-tr{display:inline-flex;align-items:center;gap:7px;height:32px;padding:0 10px 0 6px;border-radius:var(--dm-r-pill);background:var(--dm-surface);box-shadow:var(--dm-on-tint-btn);font-size:13px;font-weight:500;white-space:nowrap;transition:box-shadow .16s}
@media (hover:hover) and (pointer:fine){.mpk-tr:hover{box-shadow:var(--dm-on-tint-btn-h)}}
:root:not([data-style="soft"],[data-style="clean"]) .mpk-tr:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){box-shadow:var(--dm-shadow)}
@media (hover:hover) and (pointer:fine){:root:not([data-style="soft"],[data-style="clean"]) .mpk-tr:hover:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){box-shadow:var(--dm-shadow-pop)}}
.mpk-tr>svg{color:var(--dm-muted);transition:transform .32s var(--dm-ease)}
.mpk-tr[aria-expanded="true"]>svg{transform:rotate(180deg)}
.mpk-tr:focus-visible{outline:2px solid var(--dm-focus);outline-offset:2px}
.mpk-ef{font-weight:400;font-size:12.5px}
/* each model's mark carries the letter colour that reads on it (--dm-mt): on the accent fill that is --dm-on-accent */
.mpk-mk{width:20px;height:20px;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));display:grid;place-items:center;font-size:11px;font-weight:500;color:var(--dm-mt,var(--dm-on-ink));background:var(--dm-mc,var(--dm-fg2));flex:none;transition:background .32s}
.mpk-p{padding:6px;display:flex;flex-direction:column}
.mpk-hd,.mpk-o{display:grid;grid-template-columns:20px minmax(0,1fr) repeat(3,34px);align-items:center;gap:10px}
.mpk-hd{padding:var(--dm-s-1) 10px 2px;font-size:11px;color:var(--dm-muted)}
.mpk-hd span{text-align:center}
.mpk-o{width:100%;padding:var(--dm-s-2) 10px;border-radius:var(--dm-r-in);text-align:left;font-size:13px;transition:background .16s}
@media (hover:hover) and (pointer:fine){.mpk-o:hover{background:var(--dm-row)}}
/* (the picked model: the accent's tint, a step stronger than the selection wash so it shows on the card) */
.mpk-o[aria-checked="true"]{background:var(--dm-accent-bg)}
.mpk-o[aria-checked="true"] .d{color:var(--dm-fg2)}
.mpk-o:focus-visible{outline:2px solid var(--dm-focus);outline-offset:-2px}
.mpk-o .t{display:flex;flex-direction:column;min-width:0}
.mpk-o .t b{font-weight:500;display:flex;align-items:center;gap:6px}
.mpk-o .ck{display:grid;color:var(--dm-accent-fg,var(--dm-accent));opacity:0;transform:scale(.6);transition:opacity .16s,transform .32s var(--dm-ease)}
.mpk-o[aria-checked="true"] .ck,.mpk-o .ck:has(.spin){opacity:1;transform:none}
.mpk-o .ck .spin{width:10px;height:10px;color:var(--dm-muted)}
.mpk-o .d{font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mpk-o.busy .d{color:var(--dm-warn)}
.mpk-o.busy .mpk-mk{background:var(--dm-warn-mark);color:var(--dm-on-ink)}
.mpk-m{display:flex;gap:2px;height:8px}
.mpk-m i{flex:1;border-radius:var(--dm-r-tiny,2px);background:var(--dm-rail);transition:background .32s}
.mpk-m i.on{background:var(--dm-fg2)}
.mpk-o[aria-checked="true"]:not(.busy) .mpk-m i.on{background:var(--dm-accent-mark,var(--dm-accent))}
/* the way out when a model can't take the request: wait for it, or a close match that starts now. A warning notice (owner,
   18 Nov): a faint warning tint as wide as the rows' fills, the filled warning sign in the rows' tile column, the words in
   the text colour on the names' column, and the action in its status tint (.pill.warn), ending where the meters end */
.mpk-sg{margin:var(--dm-s-1) 0 2px;padding:10px;border-radius:var(--dm-r-in);background:color-mix(in srgb,var(--dm-warn-bg) 45%,transparent);display:grid;grid-template-columns:20px minmax(0,1fr);align-items:start;gap:10px}
.mpk-sgi{grid-area:1/1;justify-self:center;width:16px;height:16px;margin-top:1px;overflow:visible}
.mpk-sgi .a{fill:var(--dm-warn-mark);stroke:var(--dm-warn-mark);stroke-width:2;stroke-linejoin:round}
.mpk-sgi .b{fill:none;stroke:var(--dm-surface);stroke-width:2.2;stroke-linecap:round}
.mpk-sgt{grid-area:1/2;margin:0;font-size:12.5px;line-height:18px;color:var(--dm-fg)}
.mpk-sga{grid-area:2/1/3/3;display:flex;justify-content:flex-end;flex-wrap:wrap;gap:6px}
/* on the tinted notice the secondary button is white, not grey */
.mpk-sg .pill.line{background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-on-tint-btn)}
@media (hover:hover) and (pointer:fine){.mpk-sg .pill.line:hover{box-shadow:var(--dm-on-tint-btn-h)}}
/* (Blueprint draws the white button's hairline inside it, so it is as tall as the warning button beside it) */
:root:not([data-style="soft"],[data-style="clean"]) .mpk-sg .pill.line:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent)}
@media (hover:hover) and (pointer:fine){:root:not([data-style="soft"],[data-style="clean"]) .mpk-sg .pill.line:hover:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){box-shadow:inset 0 0 0 1px var(--dm-line)}}
.mpk-th{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:var(--dm-s-2) var(--dm-s-3);padding:var(--dm-s-4) 10px 10px;margin:6px 0 0;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
/* Thinking sits on the rows' columns: its icon centred in the tiles' column, its words on the names' column */
.mpk-thh{display:grid;grid-template-columns:20px minmax(0,1fr);align-items:center;column-gap:10px;min-width:0;font-size:13px}
.mpk-thh b{font-weight:500}
.mpk-thh>svg{justify-self:center;color:var(--dm-muted)}
/* (the label and its detail: one under the other here; side by side on one baseline in Clean) */
.mpk-tw{display:contents}
.mpk-thd{grid-column:2;font-size:12px}
.mpk-eb{display:inline-flex;align-items:center;gap:6px;height:28px;padding:0 var(--dm-s-2) 0 10px;border-radius:var(--dm-r-pill);background:var(--dm-chip-fill);font-size:13px;transition:background .16s}
.mpk-eb[aria-expanded="true"]{background:var(--dm-chip-fill-h)}
@media (hover:hover) and (pointer:fine){.mpk-eb:hover{background:var(--dm-chip-fill-h)}}
.mpk-eb>svg{color:var(--dm-muted);transition:transform .32s var(--dm-ease)}
.mpk-eb[aria-expanded="true"]>svg{transform:rotate(180deg)}
.mpk-pop{min-width:220px}
.mpk-note{margin:0;padding:0 2px;font-size:12.5px;min-height:20px;display:flex;align-items:center;gap:6px}
.mpk-note svg{color:var(--dm-ok);flex:none}
/* its motion (owner's trial, 26 Nov; the core's motion pieces): the list grows out of the trigger's corner from a short blur as
   the fold opens, its rows settling one after another, and folds back into it quicker than it came. A picked model's tick
   springs in out of a blur; the trigger's mark and words crossfade and its box eases to the new words' width; the effort menu
   grows from its button, and one highlight glides from row to row in every style. A press shows at once */
.mpk-p{transform-origin:top right;transition:opacity var(--dm-t-out) var(--dm-ease-io),transform var(--dm-t-out) var(--dm-ease-io),filter var(--dm-t-out) var(--dm-ease-io)}
.mpk-fold:not(.shut) .mpk-p{transition:opacity calc(var(--dm-t-in) * .6) var(--dm-ease),transform var(--dm-t-in) var(--dm-ease-pop),filter calc(var(--dm-t-in) * .7) var(--dm-ease)}
.mpk-fold.shut .mpk-p{opacity:0;transform:scale(.96);filter:blur(var(--dm-blur-in))}
.mpk-o .ck{filter:blur(var(--dm-blur-ic));transition:opacity .16s,transform var(--dm-t-in) var(--dm-ease-pop),filter var(--dm-t-fast)}
.mpk-o:is([aria-checked="true"],:has(.spin)) .ck{filter:none}
/* phones: the line under each name wraps, and the meters keep room for their labels */
/* on a phone the meters close up so a model's line keeps two or three words to a row */
@media (max-width:480px){.mpk-hd,.mpk-o{grid-template-columns:20px minmax(0,1fr) repeat(3,34px);gap:6px}.mpk-hd{font-size:10.5px;padding-inline:6px}.mpk-o,.mpk-th,.mpk-sg{padding-inline:6px}:is(.mpk-sg,.mpk-thh){column-gap:6px}.mpk-o .d{white-space:normal}}
/* Clean (owner, 18 Nov): one measure inside the popover. Its content sits 16px in from each edge: the column heads, each
   row's mark and meters (the rows sit 8px in, with 8px of their own) and the foot's text. The picked row's fill is
   concentric with the popover's corners (22px = its 14px + the 8px inset), and the foot strip's select sits 16px from the
   right edge and from the strip's top and bottom (owner, 23 Nov), a 28px pill. Selection is neutral: a grey row fill, an ink check, meters one step
