DM.def('inline-text-diff', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{chk}', I('check','xs')).replace('{x}', I('x','xs'));
  // the copy, and the agent's edits to it: what it said, what the agent suggests, and why, when the agent isn't sure
  const T = [{ o:'Pick', n:'Choose' }, ' a plan that ', { o:'fits your team', n:'grows with your studio' }, '. Every plan ', { o:'includes', n:'comes with' }, ' unlimited projects, and ', { o:'you can cancel at any time', n:'your first month is free', why:'Not in the pricing brief: there is no free month' }, '.'];
  const E = T.filter(x => typeof x === 'object');
  const root = $('.itd', r), tx = $('.itd-t', r), st = $('.itd-st', r), bar = $('.itd-bar', r), why = $('.itd-why', r), f = $('.itd-f', r), acts = $('.itd-a', r), acc = $('.itd-acc', r), rej = $('.itd-rej', r);
  // no room is kept for the end: the card eases shorter as edits fold into the text, and grows for the note at the end.
  // grow() starts once the card's entrance (which scales it from .98 in Clean) has ended, so it measures its real size
  Promise.resolve().then(() => Promise.all(root.getAnimations().map(a => a.finished.catch(() => {})))).then(() => { if (!c.dead && root.isConnected) c.offs.push(grow(root)); });
  tx.innerHTML = T.map(x => typeof x === 'string' ? x : `<span class="itd-c${x.why ? ' unsure' : ''}" role="button" tabindex="0" aria-haspopup="dialog" aria-expanded="false"><del>${x.o}</del><ins>${x.n}</ins></span>`).join('');
  const chunks = $$('.itd-c', tx);
  E.forEach((e, i) => { e.s = ''; chunks[i].setAttribute('aria-label', `Edit ${i + 1} of ${E.length}: ${e.o}, suggested ${e.n}`); });
  let cur = -1;
  function tally(){
    const n = E.filter(e => !e.s).length, a = E.filter(e => e.s === 'acc').length;
    swap(st, n === E.length ? `${n} edits to review` : n ? `${n} of ${E.length} left` : `${a} accepted, ${E.length - a} rejected`);
    // the note comes in a beat after the card starts to grow for it, so it never shows past the card's edge
    if (!n && !f.textContent){ acts.hidden = true; f.innerHTML = `${I('ok','xs')}<span>Saved to Pricing v4</span>`; enter(f, 220); }
  }
  const close = () => { bar.classList.remove('open'); bar.inert = true; chunks.forEach(x => { x.classList.remove('on'); x.setAttribute('aria-expanded', false); }); cur = -1; };
  // the toolbar opens under the edit's last line, or over its first when the stage or the page has no room below it;
  // inside a scaled preview the offsets are divided by its scale
  function open(i){
    cur = i; const el = chunks[i], e = E[i];
    chunks.forEach((x, k) => { x.classList.toggle('on', k === i); x.setAttribute('aria-expanded', k === i); });
    why.hidden = !e.why; $('span', why).textContent = e.why || '';
    // an edit the agent isn't sure of: the toolbar is a warning notice, and Reject, which settles it, is .pill.warn
    bar.classList.toggle('unsure', !!e.why);
    acc.className = 'pill sm itd-acc ' + (e.why ? 'line' : 'primary'); rej.className = 'pill sm itd-rej ' + (e.why ? 'warn' : 'ghost');
    const rb = root.getBoundingClientRect(), k = rb.width / root.offsetWidth || 1, rs = el.getClientRects(), cr = rs[rs.length - 1] || el.getBoundingClientRect(), c0 = rs[0] || cr;
    const room = popRoom(el), up = cr.bottom + 6 + bar.offsetHeight * k > room.bottom - 8 && c0.top - 6 - bar.offsetHeight * k >= room.top + 8;
    bar.inert = false; bar.classList.toggle('up', up); void bar.offsetWidth; bar.classList.add('open');
    bar.style.left = Math.max(12, Math.min(((up ? c0 : cr).left - rb.left) / k, root.offsetWidth - bar.offsetWidth - 12)) + 'px';
    bar.style.top = (up ? (c0.top - rb.top) / k - 6 - bar.offsetHeight : (cr.bottom - rb.top) / k + 6) + 'px';
  }
  // each decision folds an edit into plain text, and the last swaps the actions for a short note; the card eases to fit
  function decide(i, s){ E[i].s = s; chunks[i].classList.remove('acc', 'rej'); chunks[i].classList.add(s); tally(); }
  // a click anywhere else on the page can close the toolbar between the story's taps, and then there is no edit to decide
  // the focus goes back to the edit, with a ring only when the answer came from the keyboard (a click never leaves one)
  const pick = s => { const i = cur; if (i < 0) return; const back = bar.contains(document.activeElement); close(); decide(i, s); if (back) giveBack(chunks[i]); };
  // Enter or Space opens an edit's toolbar with the focus on Accept, as a dialog takes the focus; Escape brings it back
  chunks.forEach((el, i) => { el.onclick = () => cur === i ? close() : open(i); el.onkeydown = ev => { if (ev.key === 'Enter' || ev.key === ' '){ ev.preventDefault(); el.click(); if (cur === i) $('.itd-acc', r).focus({ preventScroll:true }); } }; });
  // the left and right arrows move between Accept and Reject
  c.on(bar, 'keydown', ev => { const bs = $$('button', bar), j = bs.indexOf(document.activeElement), d = { ArrowRight:1, ArrowDown:1, ArrowLeft:-1, ArrowUp:-1 }[ev.key];
    if (j < 0) return; const to = d ? bs[(j + d + bs.length) % bs.length] : ev.key === 'Home' ? bs[0] : ev.key === 'End' ? bs[bs.length - 1] : null;
    if (to){ ev.preventDefault(); to.focus({ preventScroll:true }); } });
  $('.itd-acc', r).onclick = () => pick('acc');
  $('.itd-rej', r).onclick = () => pick('rej');
  $('.itd-ok', r).onclick = () => { close(); E.forEach((e, i) => { if (!e.s) decide(i, 'acc'); }); };
  $('.itd-no', r).onclick = () => { close(); E.forEach((e, i) => { if (!e.s) decide(i, 'rej'); }); };
  // Escape or a click elsewhere closes the toolbar
  c.on(r, 'keydown', ev => { if (ev.key === 'Escape' && cur >= 0){ const el = chunks[cur]; close(); el.focus({ preventScroll:true }); } });
  c.on(document, 'pointerdown', ev => { if (cur >= 0 && !bar.contains(ev.target) && !ev.target.closest('.itd-c')) close(); });
  bar.inert = true; tally();
  // the preview's story: accept two edits, read why the agent isn't sure of one and reject it, then accept the rest
  c.story(async s => {
    await s.beat(4);
    await s.tap(chunks[0]); await s.beat(2); await s.tap($('.itd-acc', r)); await s.beat(1);
    await s.tap(chunks[1]); await s.beat(2); await s.tap($('.itd-acc', r)); await s.beat(1);
    await s.tap(chunks[3]); await s.beat(5); await s.tap($('.itd-rej', r)); await s.beat(3);
    await s.tap($('.itd-ok', r)); s.away();
    await s.beat(3);
  });
});

c114.css:
/* ---------- Agent tree ---------- */
/* an orchestrator and the agents it hands work to, as a tree that grows while the run plays: a header with the run's title,
   its status, the time and the total cost, then the tree. A parent's line runs down from its mark and each child branches
   off it; Soft turns each corner with a curve, Blueprint cuts it at 45 degrees. A line is one tint (the accent mixed into
   the surface) once its step has started, the grey rail while it is queued, and the bad colour only for a failed step.
   Agents keep their colours on their avatars and apps show their own logos; lines never take them. The script draws the
   lines every frame from where the marks are, so they end 1px under the mark they meet and never trail a row that moved,
   and a new row opens its space, its line draws to it, then it rises in. One soft highlight band per agent eases down its
   route to the step that agent is on. Marks are small (14px): a ring while queued, a spinner while running, a filled disc
   with a tick or a cross once done or failed (cut out of the line by a border in the surface colour), the accent disc
   where the run starts, and an accent ring with a dot while a step waits for a person */
.atr{--dm-atr-ind:22px;--dm-atr-r:8;--dm-atr-cut:0;--dm-atr-run:var(--dm-accent-mark,var(--dm-accent));--dm-atr-flow:color-mix(in srgb,var(--dm-atr-run) 30%,var(--dm-surface));--dm-atr-ez:cubic-bezier(.22,1,.36,1);container:atr/inline-size;box-sizing:border-box;width:100%;max-width:480px;margin:0 auto;padding:11px var(--dm-s-4) var(--dm-s-1);font-size:13px;line-height:1.4;color:var(--dm-fg)}
/* its content sits 16px in from every edge (owner, 18 Nov): the head's words, the foot's hairline and words, and each row's
   mark and trailing cost on the 16px column, with the row's hover fill reaching 8px out round it into the padding (owner,
   26 Nov: rows keep the head's and foot's columns); nothing in it grows or shrinks when it is pressed */
.atr :is(.pill,.ib):active{transform:none}
:root:not([data-style="soft"],[data-style="clean"]) .atr:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){--dm-atr-r:10;--dm-atr-cut:1}
.atr.bare{max-width:none;padding:0}
.atr-h{display:flex;align-items:flex-start;justify-content:space-between;gap:var(--dm-s-3);padding:var(--dm-s-1) 0 var(--dm-s-3)}
.atr.slim .atr-h{display:none}
.atr-hd{display:flex;flex-direction:column;gap:2px;min-width:0}
.atr-t{font-size:14px;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.atr-s{display:flex;align-items:center;gap:6px;min-width:0;font-size:12.5px;color:var(--dm-muted);white-space:nowrap}
.atr-dot{width:6px;height:6px;flex:none;border-radius:50%;background:var(--dm-atr-run)}
.atr[data-s="done"] .atr-dot{background:var(--dm-ok-mark)}
.atr[data-s="fail"] .atr-dot{background:var(--dm-bad-mark)}
.atr-tot{flex:none;font-size:14px;font-weight:500}
/* the tree: one treeitem per agent or step (.atr-n), its row (.atr-b) and the group of its children under it. A row holds a
   mark, an avatar or an app, the name and what it is on now, and its time and cost (a branch adds up everything under it) */
.atr-tree{position:relative;padding:var(--dm-s-1) 0}
.atr:not(.bare) .atr-tree{margin-inline:calc(-1 * var(--dm-s-2))}
.atr-n{position:relative;outline:0}
/* (a row is clicked to pick its agent, so it takes the pointer) */
.atr-b{border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk)));cursor:pointer;transition:background var(--dm-t-fast)}
/* a row's hover and its selection show on the card's white in light mode too: a quiet 5% of the text colour (owner, 18 Nov) */
@media (hover:hover) and (pointer:fine){.atr-b:hover{background:color-mix(in srgb,var(--dm-fg) 5%,transparent)}}
.atr-n[aria-selected="true"]>.atr-b{background:color-mix(in srgb,var(--dm-fg) 5%,transparent);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent)}
/* the keyboard's ring only: a row picked with the mouse or a finger shows none, even when a modifier key follows (data-nofv) */
.atr-n:focus-visible:not([data-nofv])>.atr-b{box-shadow:inset 0 0 0 2px var(--dm-focus)}
/* (a status mark is drawn 14px in its 18px box, which holds the waiting ring's halo, so the box starts 2px early and the mark
   itself sits on the content's 16px column) */
.atr-r{display:flex;align-items:center;gap:var(--dm-s-2);min-height:32px;padding:0 var(--dm-s-2) 0 calc(var(--dm-s-2) - 2px + var(--dm-lv,0) * var(--dm-atr-ind))}
/* the mark sits over the lines; the parts beside it rise in, so the mark never moves off the end of its line */
.atr-g{position:relative;z-index:2;width:18px;height:18px;flex:none;display:grid;place-items:center;border-radius:50%;color:var(--dm-line-strong)}
.atr-ring{width:14px;height:14px;box-sizing:border-box;border-radius:50%;background:var(--dm-surface);box-shadow:inset 0 0 0 1.75px currentColor}
.atr-spin{width:14px;height:14px;box-sizing:border-box;border-radius:50%;border:2px solid color-mix(in srgb,var(--dm-atr-run) 22%,var(--dm-surface));border-top-color:var(--dm-atr-run);background:var(--dm-surface);animation:atrrot .8s linear infinite}
