  }
  // the way on, in place under a row: a fix for a failed step, or Approve and Hold for one that needs a person
  function ask(n, how){
    const old = $(':scope>.atr-b>.atr-ask:not(.atr-gone)', n.el); if (old) atrDrop(old);
