    await s.until(() => here(by('des2')) && L.phase('des2') === 'shown'); await s.beat(2);
    await s.point($(':scope>.atr-b .atr-c', by('des').el)); await s.beat(3); s.away();
    await s.until(() => $('.atr-yes', r)); await s.beat(3);
    await s.tap($('.atr-yes', r)); s.away();
    await s.until(() => ended);
  });
  paint();
});

