DM.def('scheduled-runs', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{plus}', I('plus','xs')).replace('{clock}', I('clock','xs'));
  // in this preview it is Saturday afternoon, so Monday at 9:00 is two days off, and every new schedule runs at 9:00. A run's
  // mark is its tool's logo, or its icon on a vivid tile of its colour
  const R = [
    { mark:'palette', col:'l', name:'Weekly design QA', when:'Mondays at 9:00', next:'Next in 2 days', on:true, res:'ok', ago:'5 days ago' },
    { mark:'@figma', name:'Sync tokens from Figma', when:'Every day at 8:00', next:'Next in 17h', on:true, res:'bad', why:'Figma token expired', fix:'Reconnect Figma' },
    { mark:'chart', col:'t', name:'Competitor price check', when:'Fridays at 17:00', next:'Next in 6 days', on:true, res:'ok', ago:'yesterday' }
  ];
  const root = $('.shx', r) || r, list = $('.shx-list', r), add = $('.shx-add', r), pop = $('.shx-pop', r), form = $('.shx-f', r);
  const inp = $('.shx-in', r), days = $('.shx-days', r), sum = $('.shx-sum', r), mk = $('.shx-mk', r);
  function row(x){
    const ic = x.mark[0] === '@' ? `<span class="ic brandic" aria-hidden="true">${BRAND[x.mark.slice(1)]}</span>` : `<span class="ic" style="background:var(--dm-av-${x.col});color:var(--dm-av-${x.col}-ink)" aria-hidden="true">${I(x.mark,'xs')}</span>`;
    x.el = html(`<div class="shx-r" role="listitem">${ic}<span class="t"><span class="nm"></span><span class="d"></span><span class="res"></span></span><span class="shx-act"><button class="ib shx-run" data-tip="Run now">${I('play')}</button><button class="toggle" role="switch"></button></span><div class="shx-fx fold shut" inert><div><div><button class="pill accent sm shx-fix"></button></div></div></div></div>`);
    $('.nm', x.el).textContent = x.name; $('.shx-run', x.el).setAttribute('aria-label', 'Run ' + x.name + ' now'); $('.toggle', x.el).setAttribute('aria-label', x.name);
    $('.shx-run', x.el).onclick = () => run(x);
    $('.toggle', x.el).onclick = () => { x.on = !x.on; paint(x); };
    $('.shx-fix', x.el).onclick = () => fix(x);
    paint(x, true); return x.el;
  }
  // the result line, led by its mark: a tick when it passed, a sign when it failed, a turning ring while it runs (its words
  // shimmer, as every line of a process at work)
  function paint(x, now){
    const el = x.el, put = (e, t, h) => now ? (h ? e.innerHTML = t : e.textContent = t) : swap(e, t, h);
    el.classList.toggle('off', !x.on); el.dataset.st = x.run ? 'run' : x.res || 'none';
    const tg = $('.toggle', el); tg.setAttribute('aria-checked', x.on); tg.dataset.tip = x.on ? 'Pause' : 'Resume';
    put($('.d', el), x.when + ' · ' + (x.on ? x.next : 'Paused'));
    const res = document.createElement('span'); res.textContent = x.run ? 'Running now' : x.res === 'ok' ? 'Passed ' + x.ago : x.res === 'bad' ? 'Failed: ' + x.why : 'No runs yet';
    if (x.run) res.className = 'shim';
    put($('.res', el), (x.run ? '<span class="spin" aria-hidden="true"></span>' : x.res ? I(x.res === 'ok' ? 'ok' : 'alert', 'xs') : '') + res.outerHTML, true);
    $('.shx-run', el).disabled = !!x.run || !x.on;
    const fx = $('.shx-fx', el), on = x.res === 'bad' && !x.run, b = $('.shx-fix', el);
    if (on && !x.fixing){ b.textContent = x.fix; b.removeAttribute('aria-disabled'); }
    fx.classList.toggle('shut', !on); fx.inert = !on;
  }
  // Run now: the result's ring turns while it runs, then it passes
  function run(x){
    if (x.run) return; x.run = true; paint(x);
    c.later(3000, () => { x.run = false; x.res = 'ok'; x.ago = 'just now'; paint(x); });
  }
  // the fix for a failed run reconnects, then runs it again straight away. The button is as wide as its words and eases to
  // the new ones
  function fix(x){
    if (x.fixing) return; x.fixing = true; const b = $('.shx-fix', x.el), w0 = b.getBoundingClientRect().width;
    // it keeps its colour while it reconnects, and takes no second press
    b.setAttribute('aria-disabled', 'true'); b.innerHTML = '<span class="spin"></span>Reconnecting'; const w1 = b.getBoundingClientRect().width;
    const cs = getComputedStyle(b), t = cs.getPropertyValue('--dm-t').trim();
    if (!REDUCE && Math.abs(w1 - w0) > .5) b.animate([{ width:w0 + 'px' }, { width:w1 + 'px' }], { duration:(t.endsWith('ms') ? parseFloat(t) : parseFloat(t) * 1000) || 340, easing:cs.getPropertyValue('--dm-ease').trim() || 'ease' });
    c.later(900, () => { x.fixing = false; run(x); });
  }
  // the head is the title alone: no count that repeats what the rows say (the owner's notes on batch 2)
  R.forEach(x => list.appendChild(row(x))); stagger([...list.children], 50);
  // New schedule: a task in words and how often. Custom picks the days; the line under it says when the first run is
  const DAY = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'], FULL = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
  days.innerHTML = DAY.map((d, i) => `<button type="button" aria-pressed="${i === 0 || i === 2 || i === 4}" aria-label="${FULL[i]}">${d[0]}</button>`).join('');
  let rep = 'day';
  const picked = () => rep === 'day' ? [0, 1, 2, 3, 4, 5, 6] : rep === 'mon' ? [0] : $$('button', days).map((b, i) => b.getAttribute('aria-pressed') === 'true' ? i : -1).filter(i => i >= 0);
  const when = ds => ds.length === 7 ? 'Every day at 9:00' : ds.join() === '0,1,2,3,4' ? 'Weekdays at 9:00' : ds.length === 1 ? FULL[ds[0]] + 's at 9:00' : ds.map(d => DAY[d]).join(', ') + ' at 9:00';
  // today is Saturday (5) after 9:00, so tomorrow's run is 18 hours off and the rest whole days
  const next = ds => { const n = Math.min(...ds.map(d => (d - 5 + 7) % 7 || 7)); return n === 1 ? 'Next in 18h' : `Next in ${n} days`; };
  function form1(){ const ds = picked(); sum.textContent = ds.length ? next(ds).replace('Next', 'First run') : 'Pick at least one day'; mk.disabled = !inp.value.trim() || !ds.length; }
  // a menu opens over the card from its button: down when it fits below, up when it doesn't and fits above or has more room
  // there (as placePop), within the stage's room, so it never spills over the card's caption under the stage (as Artifact
  // card's version menu). The side is set on the button just before the menu is placed
  const side = (btn, pop) => { const room = popRoom(btn), st = btn.closest('.stage-inner') || btn.closest('.stage');
    if (st){ const sr = st.getBoundingClientRect(), cs = getComputedStyle(st); room.top = Math.max(room.top, sr.top + parseFloat(cs.paddingTop)); room.bottom = Math.min(room.bottom, sr.bottom - parseFloat(cs.paddingBottom)); }
    const br = btn.getBoundingClientRect(), need = pop.offsetHeight + 12, below = room.bottom - br.bottom, above = br.top - room.top;
    btn.dataset.popPos = below < need && (above >= need || above > below) ? 'up' : 'down'; };
  // the form keeps the side it opened on: one that opened upwards grows upwards, held by its bottom edge
  const replace = () => { if (!(pop.style.getPropertyValue('--dm-origin') || '').startsWith('bottom')) side(add, pop); placePop(add, pop); };
  seg($('.shx-rep', r), v => { rep = v; days.hidden = v !== 'custom'; form1(); if (pop.classList.contains('open')) replace(); });
  $$('button', days).forEach(b => b.onclick = () => { b.setAttribute('aria-pressed', b.getAttribute('aria-pressed') !== 'true'); form1(); });
  inp.oninput = form1; form1();
  c.on(add, 'click', e => { if (pop.classList.contains('open')) return; side(add, pop); if (e.isTrusted) c.later(0, () => inp.focus({ preventScroll:true })); });
  c.on(form, 'submit', e => {
    e.preventDefault(); const ds = picked(); if (!inp.value.trim() || !ds.length) return;
    const x = { mark:'clock', col:'b', name:inp.value.trim(), when:when(ds), next:next(ds), on:true, res:null };
    R.push(x); list.appendChild(row(x)); enter(x.el); closePops(); inp.value = ''; form1();
  });
  // the card grows with its rows, and eases as a fix folds open or shut (owner, 17 Nov: no room kept for a later state)
  c.offs.push(grow(root));
  // the preview's story: run the design QA now and watch it pass, reconnect Figma so the token sync passes again, then
  // pause the price check
  c.story(async s => {
    const [qa, fig, price] = R;
    await s.beat(3);
    await s.point($('.shx-run', qa.el)); await s.beat(1);
    await s.tap($('.shx-run', qa.el)); s.away();
    await s.until(() => !qa.run && qa.ago === 'just now'); await s.beat(2);
    await s.tap($('.shx-fix', fig.el)); s.away();
    await s.until(() => !fig.run && fig.res === 'ok'); await s.beat(2);
    await s.tap($('.toggle', price.el)); s.away(); await s.beat(3);
  });
});

c130.css:
/* ---------- Trace view ---------- */
/* one agent run as a waterfall: every span on a shared time axis, nested under the span that started it, with its tokens
   and latency. The run itself is the head: its mark, its name, how it is going, and its total tokens and time. The card
   sits on two columns (owner, 18 Nov): the head's mark in a 32px column with the title's words 12px after it; each span's
   mark is centred in that column (nested ones step in 16px a level) and the top spans' names start where the title's
   words do, as do the key and the Span heading. Everything sits on the card's 16px column on both sides (owner, 22 Nov: "all padding inside the card"): the
   run's totals, the times and tokens and an open span's details end 16px from the right edge, as the head's tile starts 16px
   from the left. A row's hover and selection fill is a quiet grey that reaches 8px out round the row on each side, into the
   padding, as a select's box reaches out round its words (owner, 26 Nov: rows keep the head's columns). Each kind has its colour (the chart
   palette's identity slots): its bar and its count in the key, drawn at full strength so the key matches them. While the
   run streams, a playhead marks now and the running bars grow with a bright leading edge. A span over its time budget
   turns amber and hatched, and any span opens to show where it sat in the run, its input and its output, on the same
   columns. The card keeps no room for spans still to come: it grows as each one starts (grow()) and stays centred */
.trv{width:100%;max-width:720px;margin:0 auto;padding:15px 16px 0;container-type:inline-size;--dm-cols:minmax(0,11fr) minmax(0,8fr) 40px 44px}
.trv.growing{overflow-clip-margin:0px}
.trv-h{display:flex;align-items:center;gap:12px}
.trv-hi{width:32px;height:32px;display:grid;place-items:center;flex:none;border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));color:var(--dm-fg2);background:var(--dm-chip)}
.trv-ht{flex:1;display:flex;flex-direction:column;min-width:0}
.trv-ht b{font-weight:500;font-size:14px;line-height:20px}
.trv-st{font-size:12.5px;line-height:18px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* the run's totals: its tokens, quiet, then its time over the Time column */
.trv-tt{flex:none;margin-right:-4px;font-size:12.5px;white-space:nowrap}
.trv-tot{font-size:14px;font-weight:500;flex:none}
/* (the tokens and the time share one baseline; the row round them stays centred on the tile) */
.trv-nums{flex:none;display:flex;align-items:baseline;gap:12px}
/* the key: each kind with its colour and how many of its spans have started */
.trv-lg{display:flex;flex-wrap:wrap;gap:2px var(--dm-s-3);padding:8px 0 12px 44px;font-size:12px;color:var(--dm-muted)}
.trv-lg span{display:inline-flex;align-items:center;gap:5px;white-space:nowrap;transition:color .3s}
.trv-lg i{width:8px;height:8px;border-radius:var(--dm-r-tiny,2px);background:var(--dm-k);flex:none}
.trv-lg b{font-weight:500;color:var(--dm-fg2)}
.trv-lg span.z{color:var(--dm-dis)}.trv-lg span.z b{color:inherit}.trv-lg span.z i{opacity:.45}
.trv-ax,.trv-r{display:grid;grid-template-columns:var(--dm-cols);align-items:center;gap:var(--dm-s-2)}
.trv-ax{height:30px;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:12px;color:var(--dm-muted)}
.trv-ax>span:first-child{padding-left:44px}
.trv-tk,.trv-ms{text-align:right;white-space:nowrap}
.trv-sc{position:relative;height:18px}
.trv-sc span{position:absolute;top:0;transform:translateX(-50%);font-size:12px}
.trv-sc span:first-child{transform:none}
.trv-rows{display:flex;flex-direction:column;padding-bottom:var(--dm-s-4)}
.trv-r{width:calc(100% + 16px);margin:0 -8px;padding:0 8px;min-height:32px;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));font-size:13px;text-align:left;transition:background .16s}
.trv-r[aria-expanded="true"]{background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.trv-r:hover{background:var(--dm-row)}}
.trv-r[aria-expanded="true"] .trv-tk{color:var(--dm-fg2)}
.trv-r:focus-visible{outline:0;box-shadow:inset 0 0 0 2px var(--dm-focus)}
.trv-n{position:relative;display:flex;align-items:center;gap:19px;min-width:0;align-self:stretch;padding-left:calc(7px + var(--dm-lv,0) * 16px)}
.trv-k{position:relative;z-index:1;width:18px;height:18px;display:grid;place-items:center;flex:none;border-radius:var(--dm-r-tiny,5px);color:color-mix(in srgb,var(--dm-k) 70%,var(--dm-fg));background:color-mix(in srgb,var(--dm-k) 13%,var(--dm-surface))}
.trv-nm{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.trv-n .tag{flex:none;margin-left:-11px}
/* the tree: a guide from each parent's mark down past its children, with an elbow into each child */
.trv-g{position:absolute;top:0;bottom:0;left:0;pointer-events:none}
.trv-g i{position:absolute;top:0;bottom:0;left:calc(var(--dm-x) * 16px + 15.5px);width:1px;background:color-mix(in srgb,var(--dm-rail) 60%,transparent)}
.trv-g i.end{bottom:50%}
.trv-g i.el::after{content:"";position:absolute;left:0;top:calc(50% - 1px);width:7px;height:1px;background:inherit}
.trv-g i.end.el::after{top:auto;bottom:-1px}
.trv-g i.dn{top:50%}
/* a bar per span on the shared axis: faint lines mark the ticks */
.trv-b{position:relative;height:20px;background:linear-gradient(to right,var(--dm-line) 1px,transparent 1px) 0 0/20% 100%}
/* a bar is laid out once at its full length; while it runs, --dm-f (0 to 1) reveals it with a clip and moves its bright edge with a
   transform, so a streaming run repaints without laying the page out again */
.trv-b i{position:absolute;top:5px;height:10px;min-width:3px;border-radius:var(--dm-r-tiny,3px);clip-path:inset(-6px calc((1 - var(--dm-f,1)) * 100% - 2px) -6px -6px);background:var(--dm-k);transition:background .3s,opacity .3s}
.trv-r.run:not([data-k="agent"]) .trv-b i::after{content:"";position:absolute;left:0;right:0;top:-2px;bottom:-2px;--dm-e:var(--dm-k);background:linear-gradient(to left,var(--dm-e) 0 2px,transparent 2px);transform:translateX(calc(var(--dm-f,1) * 100% - 100% + 1px))}
/* an agent span holds the others, so it is drawn as a bracket over the time they take */
.trv-r[data-k="agent"] .trv-b i,.trv-r.run[data-k="agent"] .trv-b i{top:9px;height:2px;border-radius:1px;background:var(--dm-faint);animation:none}
.trv-r[data-k="agent"] .trv-b i::before,.trv-r[data-k="agent"] .trv-b i::after{content:"";position:absolute;top:-3px;width:2px;height:8px;border-radius:1px;background:var(--dm-faint)}
.trv-r[data-k="agent"] .trv-b i::before{left:0}.trv-r[data-k="agent"] .trv-b i::after{right:0}
.trv-r.run[data-k="agent"] .trv-b i::after{background:var(--dm-muted)}
/* over budget: amber, hatched */
.trv-r.slow .trv-b i,.trv-r.run.slow .trv-b i{background:repeating-linear-gradient(135deg,var(--dm-warn-mark) 0 3px,color-mix(in srgb,var(--dm-warn-mark) 55%,var(--dm-surface)) 3px 6px)}
.trv-r.run.slow .trv-b i::after{--dm-e:var(--dm-warn-mark)}
.trv-r .trv-tk{font-size:12px;color:var(--dm-muted)}
.trv-r .trv-ms{font-size:12.5px;color:var(--dm-fg2)}
.trv-r.slow .trv-ms{color:var(--dm-warn)}
/* the playhead: where the run is now, one line down every bar's track while it streams */
.trv-b::after,.trv-sc::after{content:"";position:absolute;left:0;right:0;top:-6px;bottom:-6px;background:linear-gradient(90deg,var(--dm-accent-mark,var(--dm-accent)) 0 1px,transparent 1px);transform:translateX(calc(var(--dm-now,0) * 100% - .5px));opacity:0;transition:opacity .4s;pointer-events:none}
.trv-sc::after{top:12px;bottom:-6px}
.trv.live .trv-b::after,.trv.live .trv-sc::after{opacity:.75}
/* an open span's details, at the card's foot on the same columns: its mark under the head's, its words on the names'
   column, its close button's glyph on the Time column */
.trv-dt{margin:0 -16px}
.trv-dc{display:flex;flex-direction:column;gap:12px;padding:10px 16px 16px 60px;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.trv-dh{position:relative;display:flex;align-items:center;gap:var(--dm-s-2);min-width:0;min-height:28px;font-size:13px}
.trv-dh>.trv-k{position:absolute;left:-37px;top:5px}
.trv-dh b{min-width:0;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.trv-dh .ib{width:28px;height:28px;margin:0 0 0 auto}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov) */
.trv :is(.ib,.pill):active,:root[data-style="clean"] .trv .ib:active,:root [data-style="clean"] .trv .ib:active,:root [data-style="clean"].trv .ib:active{transform:none}
/* where the open span sat in the run */
.trv-pos{position:relative;height:6px;border-radius:var(--dm-r-tiny,3px);background:var(--dm-line)}
