/* ---------- Run drawer ---------- */
/* the run of a workflow, in a drawer under its canvas that folds down to one line and drags taller. Its head says the run's
   state in colour (running in the accent, waiting amber, passed green, failed red, stopped grey), the time, the tokens and the
   cost, then Steps, Log and Data, Stop and Follow the run. Steps is a timeline with each step's model and tool calls nested
   under it, each bar in its kind's colour, a failed try red and the wait before a retry hatched amber. Log is the run's lines
   with their levels in colour, filtered by level. Data is what each step took in and handed on, as JSON */
.rdr{position:relative;width:100%;height:472px;container:rdrf/inline-size;display:flex;flex-direction:column;overflow:hidden;border-radius:var(--dm-r-card);background:var(--dm-surface);box-shadow:var(--dm-shadow);text-align:left}
.rdr-cv{position:relative;flex:1;min-height:0;display:flex;align-items:center;justify-content:center;padding:var(--dm-s-4);background:var(--dm-stage);background-image:radial-gradient(circle at center,color-mix(in srgb,var(--dm-fg) 9%,transparent) 1px,transparent 1.5px);background-size:16px 16px;overflow:hidden}
.rdr-flow{position:relative;display:flex;align-items:center;max-width:100%;overflow-x:auto;scrollbar-width:none;padding:6px}
.rdr-flow::-webkit-scrollbar{display:none}
.rdr-wire{flex:none;width:14px;height:1.5px;background:var(--dm-faint);transition:background .4s var(--dm-ease)}
.rdr-wire.done{background:color-mix(in srgb,var(--dm-fg) 40%,var(--dm-faint))}
.rdr-nd{position:relative;flex:none;display:flex;align-items:center;gap:6px;height:34px;padding:0 7px;border-radius:calc(7px * var(--dm-rk-m,var(--dm-rk)));background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 80%,transparent);font-size:12px;white-space:nowrap;transition:box-shadow .3s,opacity .3s}
@media (hover:hover) and (pointer:fine){.rdr-nd:hover{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line-strong) 50%,transparent)}}
.rdr-nd .t{max-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;opacity:0;transition:max-width var(--dm-t) var(--dm-ease),opacity var(--dm-t) var(--dm-ease)}
.rdr-nd:is([data-st="run"],[data-st="retry"],[data-st="wait"],[data-st="bad"],[aria-pressed="true"]) .t{max-width:132px;opacity:1}
/* every ring is drawn inside the step (owner, 18 Nov: buttons side by side are the same drawn height): a picked step's edge a step
   stronger, the running one in the accent, a failed one red and a retry or a wait amber */
.rdr-nd[aria-pressed="true"]{box-shadow:inset 0 0 0 1.5px var(--dm-line-strong)}
.rdr-nd[data-st="run"]{box-shadow:inset 0 0 0 1.5px var(--dm-accent-mark,var(--dm-accent))}
.rdr-nd[data-st="bad"]{box-shadow:inset 0 0 0 1.5px var(--dm-bad-mark)}
.rdr-nd:is([data-st="retry"],[data-st="wait"]){box-shadow:inset 0 0 0 1.5px var(--dm-warn-mark)}
.rdr-nd[data-st="skip"]{opacity:.5}
.rdr-ns{display:none;width:14px;height:14px;place-items:center;color:var(--dm-ok-mark)}
.rdr-nd[data-st="ok"] .rdr-ns{display:grid;margin-left:-2px}
.rdr-nd[data-st="ok"] .rdr-ns .i{width:12px;height:12px}
.rdr-ti{width:18px;height:18px;flex:none;display:grid;place-items:center;border-radius:calc(5px * var(--dm-rk-s,var(--dm-rk)));background:var(--dm-rdr-kb,var(--dm-chip));color:var(--dm-rdr-kf,var(--dm-fg2))}
.rdr-ti .i{width:11px;height:11px}
.rdr [data-k],.rdr-dw [data-k]{--dm-rdr-kb:var(--dm-chip);--dm-rdr-kf:var(--dm-fg2);--dm-rdr-kc:var(--dm-faint)}
.rdr [data-k="trigger"],.rdr-dw [data-k="trigger"]{--dm-rdr-kb:var(--dm-pp-bg);--dm-rdr-kf:var(--dm-pp);--dm-rdr-kc:var(--dm-pp)}
.rdr [data-k="ai"],.rdr-dw [data-k="ai"]{--dm-rdr-kb:var(--dm-pl-bg);--dm-rdr-kf:var(--dm-pl);--dm-rdr-kc:var(--dm-pl)}
.rdr [data-k="model"],.rdr-dw [data-k="model"]{--dm-rdr-kb:var(--dm-pl-bg);--dm-rdr-kf:var(--dm-pl);--dm-rdr-kc:color-mix(in srgb,var(--dm-pl) 75%,var(--dm-surface))}
.rdr [data-k="tool"],.rdr-dw [data-k="tool"]{--dm-rdr-kb:var(--dm-pt-bg);--dm-rdr-kf:var(--dm-pt);--dm-rdr-kc:var(--dm-pt)}
.rdr :is([data-k="app"],[data-k="output"]),.rdr-dw :is([data-k="app"],[data-k="output"]){--dm-rdr-kb:var(--dm-pb-bg);--dm-rdr-kf:var(--dm-pb);--dm-rdr-kc:var(--dm-pb)}
.rdr [data-k="branch"],.rdr-dw [data-k="branch"]{--dm-rdr-kb:var(--dm-py-bg);--dm-rdr-kf:var(--dm-py);--dm-rdr-kc:var(--dm-py)}
.rdr [data-k="wait"],.rdr-dw [data-k="wait"]{--dm-rdr-kb:var(--dm-pk-bg);--dm-rdr-kf:var(--dm-pk);--dm-rdr-kc:var(--dm-pk)}
.rdr [data-k="approval"],.rdr-dw [data-k="approval"]{--dm-rdr-kb:var(--dm-pm-bg);--dm-rdr-kf:var(--dm-pm);--dm-rdr-kc:var(--dm-pm)}
